  }];
}

// toolCode: il parametro agente arriva come variabile 'query' (stringa).
let r;
try { r = (typeof query !== 'undefined') ? query : ($input?.first?.()?.json?.query ?? ''); } catch (e) { r = ''; }
let q = String(r||'').toLowerCase().trim();
q = q.replace(/[‘’ʼʻ`]/g, "'").replace(/\s+/g, ' ').trim();

const n = $now.setZone('Europe/Rome');
const W = {'lunedi':1,'lunedì':1,'martedi':2,'martedì':2,'mercoledi':3,'mercoledì':3,'giovedi':4,'giovedì':4,'venerdi':5,'venerdì':5,'sabato':6,'domenica':7};
const R = {'oggi':0,'stasera':0,'stamattina':0,'stanotte':0,'domani':1,'domattina':1,'domani sera':1,'domani notte':1,'dopodomani':2,'dopo domani':2};

// FIX 2026-05-21: usa luxon weekday (Europe/Rome) invece di JS getUTCDay() — risolveva la mismatch UTC
// luxon weekday: 1=Mon, 2=Tue, ..., 7=Sun
const ITALIAN_DAYS_SHORT_BY_WEEKDAY = {1:'lun',2:'mar',3:'mer',4:'gio',5:'ven',6:'sab',7:'dom'};
const ITALIAN_DAYS_FULL_BY_WEEKDAY = {1:'lunedì',2:'martedì',3:'mercoledì',4:'giovedì',5:'venerdì',6:'sabato',7:'domenica'};
const ITALIAN_MONTHS = ['gennaio','febbraio','marzo','aprile','maggio','giugno','luglio','agosto','settembre','ottobre','novembre','dicembre'];

function fmtItDate(dt) {
  // dt è un DateTime di Luxon in Europe/Rome
  const dow = ITALIAN_DAYS_SHORT_BY_WEEKDAY[dt.weekday];
  const mo = ITALIAN_MONTHS[parseInt(dt.toFormat('M'))-1];
  return `${dow} ${parseInt(dt.toFormat('d'))} ${mo} ${dt.toFormat('yyyy')}`;
}

function fmtItDateFull(dt) {
  const dow = ITALIAN_DAYS_FULL_BY_WEEKDAY[dt.weekday];
  const mo = ITALIAN_MONTHS[parseInt(dt.toFormat('M'))-1];
  return `${dow} ${parseInt(dt.toFormat('d'))} ${mo} ${dt.toFormat('yyyy')}`;
}

const oraCorrente = n.toFormat('HH:mm');
const oggi = n.toFormat('yyyy-MM-dd');
const dataOggi = fmtItDate(n);
const annoCorrente = n.year;
const timestampISO = n.toISO();

function rispondi(extra) {
  const base = { oraCorrente, oggi, dataOggi, annoCorrente, timestampISO, input: q };
  return JSON.stringify(Object.assign(base, extra || {}));
}

if (/^(ora|adesso|che\s*ore|ora\s*(corrente|attuale)|now|che\s*giorno|oggi)\s*\??$/i.test(q)) {
  return rispondi({ formattedDate: dataOggi, iso: oggi, oraTarget: oraCorrente, weekday: ITALIAN_DAYS_FULL_BY_WEEKDAY[n.weekday] });
}

const offRx = /^(?:tra|fra|in|dopo|after|after\s+)?\s*\+?\s*(\d+|mezz[a']?|un[a']?|due|tre|quattro|cinque)\s*('|h|ho|hr|hrs|ore|ora|m|min|minut[oi])?\s*(?:da\s*(?:adesso|ora))?$/i;
const wordToNum = {"mezza":0.5,"mezz'":0.5,"mezz":0.5,"un":1,"una":1,"due":2,"tre":3,"quattro":4,"cinque":5};

const mOff = q.match(offRx);
if (mOff) {
  let amt = mOff[1];
  let unitRaw = (mOff[2]||'').toLowerCase();
  let n_amt = wordToNum[amt] !== undefined ? wordToNum[amt] : parseFloat(amt);
  let isHours = /^(h|ho|hr|hrs|ore|ora)$/.test(unitRaw);
  let isMinutes = /^('|m|min|minut[oi])$/.test(unitRaw);
  if (!isHours && !isMinutes) {
    if (amt === "mezz'" || amt === "mezz" || amt === "mezza") isHours = true;
    else if (n_amt < 10) isHours = true;
    else isMinutes = true;
  }
  const dtTarget = isHours ? n.plus({minutes: Math.round(n_amt*60)}) : n.plus({minutes: Math.round(n_amt)});
  return rispondi({
    formattedDate: fmtItDate(dtTarget),
    iso: dtTarget.toFormat('yyyy-MM-dd'),
    oraTarget: dtTarget.toFormat('HH:mm'),
    offsetMinutes: Math.round((dtTarget.toMillis() - n.toMillis())/60000),
    isToday: dtTarget.toFormat('yyyy-MM-dd') === oggi,
    weekday: ITALIAN_DAYS_FULL_BY_WEEKDAY[dtTarget.weekday]
  });
}

const mezzRx = /^(mezz[a']?\s*ora|un'?\s*ora|due\s*ore|tre\s*ore)$/i;
if (mezzRx.test(q)) {
  let minutes = 0;
  if (/mezz/i.test(q)) minutes = 30;
  else if (/un'?\s*ora/i.test(q)) minutes = 60;
  else if (/due/i.test(q)) minutes = 120;
  else if (/tre/i.test(q)) minutes = 180;
  const dtTarget = n.plus({minutes});
  return rispondi({
    formattedDate: fmtItDate(dtTarget),
    iso: dtTarget.toFormat('yyyy-MM-dd'),
    oraTarget: dtTarget.toFormat('HH:mm'),
    offsetMinutes: minutes,
    isToday: dtTarget.toFormat('yyyy-MM-dd') === oggi,
    weekday: ITALIAN_DAYS_FULL_BY_WEEKDAY[dtTarget.weekday]
  });
}

let iso = null;
if (/^\d{4}-\d{2}-\d{2}$/.test(q)) iso = q;
else if (R[q] !== undefined) iso = n.plus({days:R[q]}).toFormat('yyyy-MM-dd');
else {
  for (const k of Object.keys(W)) {
    if (q===k || q.startsWith(k+' ') || q.endsWith(' '+k) || q.includes(' '+k+' ')) {
      let d = W[k] - n.weekday;
      if (d <= 0) d += 7;
      iso = n.plus({days:d}).toFormat('yyyy-MM-dd');
      break;
    }
  }
}
if (!iso) {
  // PARITA' 2026-06-16: mese a parole ("29 agosto", "29 agosto 2026"). Stessa inferenza anno del ramo dd/mm.
  const mn = q.match(/(\d{1,2})\s+(gennaio|febbraio|marzo|aprile|maggio|giugno|luglio|agosto|settembre|ottobre|novembre|dicembre)(?:\s+(\d{4}))?/);
  if (mn) {
    let dd = parseInt(mn[1]), mo = ITALIAN_MONTHS.indexOf(mn[2]) + 1;
    let yy = mn[3] ? parseInt(mn[3]) : n.year;
    let dt = n.set({year: yy, month: mo, day: dd}).startOf('day');
    if (!mn[3] && dt < n.startOf('day')) dt = dt.plus({years: 1});
    iso = dt.toFormat('yyyy-MM-dd');
  }
}
if (!iso) {
  const m = q.match(/(\d{1,2})[\/\-\.](\d{1,2})(?:[\/\-\.](\d{2,4}))?/);
  if (m) {
    let dd = parseInt(m[1]), mo = parseInt(m[2]);
    let yy = m[3] ? parseInt(m[3]) : n.year;
    if (yy < 100) yy += 2000;
    let dt = n.set({year: yy, month: mo, day: dd}).startOf('day');
    if (!m[3] && dt < n.startOf('day')) dt = dt.plus({years: 1});
    iso = dt.toFormat('yyyy-MM-dd');
  }
}
if (!iso) {
  return rispondi({ error: "Non riesco a interpretare: " + q, formattedDate: dataOggi, iso: oggi, oraTarget: oraCorrente, weekday: ITALIAN_DAYS_FULL_BY_WEEKDAY[n.weekday] });
}
const parts = iso.split('-').map(Number);
const d2 = n.set({year: parts[0], month: parts[1], day: parts[2]}).startOf('day');
return rispondi({
  formattedDate: fmtItDate(d2),
  iso: iso,
  weekday: ITALIAN_DAYS_FULL_BY_WEEKDAY[d2.weekday]
});

// n8n Code node — Router + Normalize Autista (tutto in uno)
// Output: 1 item { kind, text, file_id, mime, chat_id, message_id, callback_data, Autista, AutistaRaw, MatchType, ChatId, (opzionali) contact_* }

// =====================
// 1) NORMALIZE AUTISTA
// =====================
function stripDiacritics(s) {
  return (s || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function normalizeKey(s) {
  return stripDiacritics(s)
    .toLowerCase()
    .trim()
    .replace(/[.,;:!?"'`´^~_*()\[\]{}<>|\\\/+-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function variants(sNorm) {
  const parts = sNorm.split(" ").filter(Boolean);
  const out = new Set([sNorm]);
  if (parts.length === 2) out.add(`${parts[1]} ${parts[0]}`);
  if (parts.length >= 3) out.add(`${parts[parts.length - 1]} ${parts.slice(0, parts.length - 1).join(" ")}`);
  return [...out].filter(Boolean);
}

const CANONICAL = [
  "Danilo Santomauro","Antonio Leggiero","Claudio Moccia","Eustachio Corbascio",
  "Giuseppe Giannuzzi","Giuseppe Fanelli","Davide Franco","Emanuele Pastoressa",
  "Paolo","Puglia On","Stefano Calessino","Stefano NCC","Your Driver","Vito Stoppa",
  "Agostino Narracci","Fabrizio Giangrande","Franco Di Ceglie","Ilenia Colella",
  "Modesto Colella","Nicola Narracci","Angelo Olivieri","Antonio Lanzillotti",
  "Giovanni","Marco"
];

const ALIASES = {
  "agost narracci": "Agostino Narracci",
  "agtino narracci": "Agostino Narracci",
  "agostino": "Agostino Narracci"
};

const canonMap = new Map();
for (const name of CANONICAL) canonMap.set(normalizeKey(name), name);

function normalizeAutistaFromRoot(root) {
  const sources = [root.message?.from, root.callback_query?.from, root.callback_query?.message?.chat];
  let first = "", last = "", chat_id = "";
  for (const s of sources) {
    if (s?.first_name) {
      first = String(s.first_name || "");
      last = String(s.last_name || "");
      chat_id = String(s.id ?? "");
      break;
    }
  }
  const raw = `${first} ${last}`.replace(/\s+/g, " ").trim();
  const rawNorm = normalizeKey(raw);
  if (ALIASES[rawNorm]) return { Autista: ALIASES[rawNorm], AutistaRaw: raw, MatchType: "alias", ChatId: chat_id };
  if (canonMap.has(rawNorm)) return { Autista: canonMap.get(rawNorm), AutistaRaw: raw, MatchType: "direct", ChatId: chat_id };
  for (const v of variants(rawNorm)) {
    if (ALIASES[v]) return { Autista: ALIASES[v], AutistaRaw: raw, MatchType: "alias_variant", ChatId: chat_id };
    if (canonMap.has(v)) return { Autista: canonMap.get(v), AutistaRaw: raw, MatchType: "variant", ChatId: chat_id };
  }
  return { Autista: raw, AutistaRaw: raw, MatchType: "fallback_raw", ChatId: chat_id };
}

// =====================
// 2) ROUTER
// =====================
const root = $input.first().json || {};
const u = root.message || {};
const cb = root.callback_query || {};
const aut = normalizeAutistaFromRoot(root);

const out = {
  kind: "", text: "",
  originalMessageText: cb?.message?.text ?? u?.text ?? "", file_id: "", mime: "",
  chat_id: cb?.message?.chat?.id ?? u?.chat?.id ?? aut.ChatId ?? "",
  message_id: cb?.message?.message_id ?? u?.message_id ?? "",
  callback_data: cb?.data ?? "",
  Autista: aut.Autista, AutistaRaw: aut.AutistaRaw,
  MatchType: aut.MatchType, ChatId: aut.ChatId
};

if (cb?.data) { out.kind = "callback"; out.text = String(cb.data || "").trim(); return [{ json: out }]; }
if (u?.text) { out.kind = "text"; out.text = String(u.text || "").trim(); return [{ json: out }]; }

// contact → kind "text"
if (u?.contact?.phone_number) {
  out.kind = "text";
  const phoneRaw = String(u.contact.phone_number || "").trim();
  const phone = phoneRaw.replace(/\D/g, "");
  const fn = String(u.contact.first_name || "").trim();
  const ln = String(u.contact.last_name || "").trim();
  const name = [fn, ln].filter(Boolean).join(" ").trim();
  out.text = [name ? `Nome contatto: ${name}` : null, phone ? `Telefono: ${phone}` : null].filter(Boolean).join("\n");
  out.contact_phone = phone; out.contact_phone_raw = phoneRaw; out.contact_name = name;
  return [{ json: out }];
}

if (Array.isArray(u.photo) && u.photo.length) {
  out.kind = "image"; out.file_id = u.photo.reduce(function(m,p){ return ((p.width||0)*(p.height||0) > (m.width||0)*(m.height||0)) ? p : m; }).file_id;
  out.text = String(u.caption || "").trim(); return [{ json: out }];
}
if (u?.voice?.file_id) { out.kind = "voice"; out.file_id = u.voice.file_id; out.text = String(u.caption || "").trim(); return [{ json: out }]; }
// audio → kind "voice"
if (u?.audio?.file_id) { out.kind = "voice"; out.file_id = u.audio.file_id; out.text = String(u.caption || "").trim(); return [{ json: out }]; }

if (u?.document?.file_id) {
  const docMime = String(u.document.mime_type || "");
  if (docMime.startsWith("image/")) {
    out.kind = "image"; out.file_id = u.document.file_id; out.mime = docMime;
    out.text = String(u.caption || "").trim(); return [{ json: out }];
  }
  out.kind = "document"; out.file_id = u.document.file_id; out.mime = docMime;
  out.text = String(u.caption || "").trim(); return [{ json: out }];
}
out.kind = "unknown"; out.text = String(u.caption || "").trim(); return [{ json: out }];

// vCard parser v3 — JsTaskRunner safe (with iOS itemN. prefix support)
const items = $input.all();
const out = [];

function decodeQuotedPrintable(s) {
  return s.replace(/=([0-9A-Fa-f]{2})/g, function(_, h){ return String.fromCharCode(parseInt(h, 16)); }).replace(/=\r?\n/g, '');
}
function decodeValue(val, encoding, charset) {
  if (!val) return '';
  let v = val;
  if (encoding && /quoted-printable/i.test(encoding)) v = decodeQuotedPrintable(v);
  else if (encoding && /base64/i.test(encoding)) {
    try { v = Buffer.from(v, 'base64').toString(charset || 'utf8'); } catch(e){}
  }
  return v;
}
function parseLine(line) {
  const colonIdx = line.indexOf(':');
  if (colonIdx === -1) return null;
  const head = line.slice(0, colonIdx);
  const value = line.slice(colonIdx + 1);
  const headParts = head.split(';');
  // FIX iOS: rimuove prefisso "itemN." (es. item1.TEL → TEL, item2.EMAIL → EMAIL)
  const property = headParts[0].toUpperCase().replace(/^ITEM\d+\./, '');
  const params = {};
  for (let j = 1; j < headParts.length; j++) {
    const p = headParts[j];
    if (p.indexOf('=') !== -1) { const kv = p.split('='); params[kv[0].toUpperCase()] = kv[1]; }
    else params.TYPE = (params.TYPE ? params.TYPE + ',' : '') + p;
  }
  return { property: property, params: params, value: value };
}
function parseVCard(raw) {
  const lines = raw.replace(/\r\n/g, '\n').split('\n');
  const unfolded = [];
  for (let k = 0; k < lines.length; k++) {
    const ln = lines[k];
    if ((ln.charAt(0) === ' ' || ln.charAt(0) === '\t') && unfolded.length) unfolded[unfolded.length - 1] += ln.slice(1);
    else unfolded.push(ln);
  }
  const cards = [];
  let cur = null;
  for (let k = 0; k < unfolded.length; k++) {
    const ln = unfolded[k];
    if (!ln.trim()) continue;
    const upper = ln.toUpperCase();
    if (upper.indexOf('BEGIN:VCARD') === 0) { cur = { tel: [], email: [], raw: '' }; continue; }
    if (upper.indexOf('END:VCARD') === 0) { if (cur) cards.push(cur); cur = null; continue; }
    if (!cur) continue;
    cur.raw += ln + '\n';
    const parsed = parseLine(ln);
    if (!parsed) continue;
    const property = parsed.property; const params = parsed.params; const value = parsed.value;
    const decoded = decodeValue(value, params.ENCODING, params.CHARSET);
    if (property === 'FN') cur.fn = decoded;
    else if (property === 'N') {
      const parts = decoded.split(';');
      cur.n = { family: parts[0]||'', given: parts[1]||'', middle: parts[2]||'', prefix: parts[3]||'', suffix: parts[4]||'' };
    }
    else if (property === 'TEL') cur.tel.push({ value: decoded, type: params.TYPE || '' });
    else if (property === 'EMAIL') cur.email.push({ value: decoded, type: params.TYPE || '' });
    else if (property === 'ORG') cur.org = decoded.replace(/;/g,' ').trim();
    else if (property === 'TITLE') cur.title = decoded;
    else if (property === 'NOTE') cur.note = decoded;
    else if (property === 'VERSION') cur.version = decoded;
  }
  return cards;
}
function friendlyName(c) {
  if (c.fn && c.fn.trim()) return c.fn.trim();
  if (c.n) {
    const p = [c.n.prefix, c.n.given, c.n.middle, c.n.family, c.n.suffix].filter(function(x){ return x && x.trim(); }).join(' ').trim();
    if (p) return p;
  }
  return '';
}
function buildText(c) {
  const lines = [];
  const name = friendlyName(c);
  if (name) lines.push('Nome: ' + name);
  if (c.tel.length) lines.push('Telefono: ' + c.tel.map(function(t){ return t.type ? t.value + ' (' + t.type + ')' : t.value; }).join(', '));
  if (c.email.length) lines.push('Email: ' + c.email.map(function(e){ return e.value; }).join(', '));
  if (c.org) lines.push('Azienda: ' + c.org);
  if (c.title) lines.push('Ruolo: ' + c.title);
  if (c.note) lines.push('Note: ' + c.note);
  return lines.join('\n');
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  let text = '';
  let strategy = 'none';
  let lastErr = '';
  try {
    if (typeof $getBinaryDataBuffer === 'function') {
      const buf = await $getBinaryDataBuffer(i, 'data');
      if (buf && buf.length > 0) { text = buf.toString('utf8'); strategy = 'globalBinaryBuffer'; }
    }
  } catch(e) { lastErr = 'globalBinaryBuffer: ' + e.message; }
  if (!text) {
    try {
      const h = (typeof this !== 'undefined' && this) ? this.helpers : null;
      if (h && typeof h.getBinaryDataBuffer === 'function') {
        const buf = await h.getBinaryDataBuffer(i, 'data');
        if (buf && buf.length > 0) { text = buf.toString('utf8'); strategy = 'thisHelpers'; }
      }
    } catch(e) { lastErr = (lastErr ? lastErr + '; ' : '') + 'thisHelpers: ' + e.message; }
  }
  if (!text) {
    try {
      const bin = item.binary && item.binary.data;
      if (bin && typeof bin.data === 'string' && bin.data.length > 50) {
        const decoded = Buffer.from(bin.data, 'base64').toString('utf8');
        if (decoded && /BEGIN:VCARD/i.test(decoded)) { text = decoded; strategy = 'inlineBase64'; }
      }
    } catch(e) { lastErr = (lastErr ? lastErr + '; ' : '') + 'inlineBase64: ' + e.message; }
  }
  if (!text) {
    out.push({ json: { text: 'vCard non leggibile (binary vuoto)', kind: 'vcard', error: 'no_binary', diag: { hasBinary: !!item.binary, binaryKeys: item.binary ? Object.keys(item.binary) : [], dataKeys: item.binary && item.binary.data ? Object.keys(item.binary.data) : [], lastErr: lastErr, hasGlobalGetter: typeof $getBinaryDataBuffer, hasThis: typeof this } } });
    continue;
  }
  const cards = parseVCard(text);
  if (!cards.length) {
    out.push({ json: { text: 'vCard non leggibile (parsing fallito)', kind: 'vcard', error: 'parse_failed', strategy: strategy, raw: text.slice(0,500) } });
    continue;
  }
  for (let c = 0; c < cards.length; c++) {
    const card = cards[c];
    out.push({ json: { text: buildText(card) || 'vCard senza dati utili', kind: 'vcard', strategy: strategy, fn: friendlyName(card), n: card.n || null, tel: card.tel, email: card.email, org: card.org || '', title: card.title || '', note: card.note || '', version: card.version || '', raw: card.raw } });
  }
}
return out;

// Fuzzy Lookup — Matching a 3 livelli (exact, levenshtein, fonetico italiano)

var COMMON_IT_WORDS = new Set(["il","la","lo","i","gli","le","un","una","uno","del","della","dei","degli","delle","di","da","a","ad","in","per","con","su","tra","fra","al","alla","allo","ai","agli","alle","sul","sulla","sullo","sui","sugli","sulle","e","ed","o","ma","che","chi","come","cosa","dove","quando","perche","perché","se","mi","ti","si","ci","vi","ne","anche","sempre","mai","oggi","domani","dopodomani","ieri","stamattina","stasera","stanotte","mattina","mattino","pomeriggio","sera","notte","mezzogiorno","mezzanotte","weekend","giornata","ora","ore","minuto","minuti","secondo","secondi","prossimo","prossima","scorso","scorsa","adesso","lunedi","lunedì","martedi","martedì","mercoledi","mercoledì","giovedi","giovedì","venerdi","venerdì","sabato","domenica","gennaio","febbraio","marzo","aprile","maggio","giugno","luglio","agosto","settembre","ottobre","novembre","dicembre","ciao","salve","buongiorno","buonasera","buonanotte","grazie","prego","perfetto","ok","si","sì","no","forse","bene","male","tutto","niente","poco","molto","tanto","quanto","avere","essere","fare","andare","venire","partire","arrivare","prenotare","confermare","ho","hai","ha","abbiamo","avete","hanno","sono","sei","è","siamo","siete","vado","vai","va","andiamo","andate","vanno","farò","andrò","verrò","voglio","vorrei","vorremmo","transfer","pickup","prenotazione","prenotazioni","cliente","clienti","passeggero","passeggeri","pax","bagaglio","bagagli","volo","voli","treno","treni","bus","auto","macchina","macchine","van","furgone","autista","autisti","tariffa","tariffe","euro","prezzo","prezzi","orario","orari","data","date","nome","cognome","telefono","cellulare","aeroporto","stazione","porto","servizio","servizi","tour","giro","extra","uno","due","tre","quattro","cinque","sei","sette","otto","nove","dieci","undici","dodici","tredici","quattordici","quindici","sedici","diciassette","diciotto","diciannove","venti","trenta","quaranta","cinquanta","sessanta","settanta","ottanta","novanta","cento","mille","confermi","conferma","confermato","annulla","annullato","annullata","modifica","modificato","modificata","cancella","cancellato","cancellazione","cancellare","domanda","risposta","messaggio","chat","dalle","dall","fino","appena","subito","questo","questa","questi","queste","quello","quella","quelli","quelle","mio","mia","miei","mie","tuo","tua","tuoi","tue","suo","sua","suoi","sue","nostro","nostra","nostri","nostre","vostro","vostra","vostri","vostre","inserimento","aggiungere","togliere","rimuovere","serve","servono","bisogno","bisogna","piu","più","meno","soltanto","solo","anche","ancora","gia","già","verso","circa"]);
function isCommonItalianWord(s) {
  if (!s) return true;
  var n = String(s).toLowerCase().replace(/[\u00e0\u00e1\u00e2\u00e3]/g,'a').replace(/[\u00e8\u00e9\u00ea]/g,'e').replace(/[\u00ec\u00ed]/g,'i').replace(/[\u00f2\u00f3\u00f4]/g,'o').replace(/[\u00f9\u00fa]/g,'u').trim();
  if (n.length < 4) return true;
  var parts = n.split(/\s+/);
  return parts.every(function(p){ return COMMON_IT_WORDS.has(p); });
}

function shareStartingLetters(a, b, n) {
  if (!a || !b) return false;
  var na = String(a).toLowerCase().replace(/[\u00e0\u00e1\u00e2\u00e3]/g,'a').replace(/[\u00e8\u00e9\u00ea]/g,'e').replace(/[\u00ec\u00ed]/g,'i').replace(/[\u00f2\u00f3\u00f4]/g,'o').replace(/[\u00f9\u00fa]/g,'u').trim();
  var nb = String(b).toLowerCase().replace(/[\u00e0\u00e1\u00e2\u00e3]/g,'a').replace(/[\u00e8\u00e9\u00ea]/g,'e').replace(/[\u00ec\u00ed]/g,'i').replace(/[\u00f2\u00f3\u00f4]/g,'o').replace(/[\u00f9\u00fa]/g,'u').trim();
  if (na.length < n || nb.length < n) return na === nb;
  return na.substring(0, n) === nb.substring(0, n);
}

function stripDiacritics(s) {
  s = String(s || '');
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
function normalize(s) {
  s = String(s || '');
  return stripDiacritics(s).toLowerCase().trim()
    .replace(/[^a-z0-9\u00e0\u00e8\u00e9\u00ec\u00f2\u00f9 ]/g, '').replace(/\s+/g, ' ');
}

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const d = Array.from({length: m + 1}, () => Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) d[i][0] = i;
  for (let j = 0; j <= n; j++) d[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i-1] === b[j-1] ? 0 : 1;
      d[i][j] = Math.min(d[i-1][j] + 1, d[i][j-1] + 1, d[i-1][j-1] + cost);
      if (i > 1 && j > 1 && a[i-1] === b[j-2] && a[i-2] === b[j-1]) {
        d[i][j] = Math.min(d[i][j], d[i-2][j-2] + cost);
      }
    }
  }
  return d[m][n];
}

function phoneticIT(s) {
  let p = normalize(s);
  p = p.replace(/([bcdfglmnpqrstvz])\1+/g, '$1');
  p = p.replace(/ch/g, 'k').replace(/ck/g, 'k').replace(/gh/g, 'g');
  p = p.replace(/gn/g, '\u00f1').replace(/gli/g, '\u028e');
  p = p.replace(/sci/g, '\u0283i').replace(/sce/g, '\u0283e').replace(/sc([aou])/g, 'sk$1');
  p = p.replace(/ci([aou])/g, 't\u0283$1').replace(/ce/g, 't\u0283e').replace(/ci/g, 't\u0283i');
  p = p.replace(/gi([aou])/g, 'd\u0292$1').replace(/ge/g, 'd\u0292e').replace(/gi/g, 'd\u0292i');
  p = p.replace(/qu/g, 'kw').replace(/cu([aeiou])/g, 'kw$1').replace(/h/g, '');
  return p;
}

// ============================================================
// FIX AMBIGUITA' (2026-06-06): bestMatch -> bestMatches (top 3)
// e findEntities con rilevazione ambiguita'. Caso reale:
// "coco beach club" matchava SOLO "Coccaro Beach club" (fonetico
// 0.89) e nascondeva "Cocco Beach" (quasi esatto). Ora quando due
// luoghi diversi hanno punteggi vicini l'output segnala
// ambiguous:true + candidates e l'AI DEVE chiedere all'utente.
// ============================================================

function preparaCandidati(candidates) {
  // Chiavi calcolate una volta sola + due indici per lunghezza (normalizzata e fonetica).
  const pronti = [];
  for (const c of candidates) {
    if (!c) continue;
    pronti.push({ orig: c, norm: normalize(c), phon: phoneticIT(c), i: pronti.length });
  }
  const perNorm = new Map(), perPhon = new Map();
  for (const p of pronti) {
    const a = p.norm.length, b = p.phon.length;
    if (!perNorm.has(a)) perNorm.set(a, []);
    perNorm.get(a).push(p);
    if (!perPhon.has(b)) perPhon.set(b, []);
    perPhon.get(b).push(p);
  }
  return { tutti: pronti, perNorm: perNorm, perPhon: perPhon };
}

// Solo i candidati che possono davvero passare una delle tre porte:
// levenshtein e «contenuto» chiedono lunghezze entro 5, il fonetico entro 3.
function candidatiPossibili(pronti, lenNorm, lenPhon) {
  const visti = new Set(), fuori = [];
  for (let L = lenNorm - 5; L <= lenNorm + 5; L++) {
    const g = pronti.perNorm.get(L);
    if (!g) continue;
    for (const p of g) if (!visti.has(p)) { visti.add(p); fuori.push(p); }
  }
  for (let L = lenPhon - 3; L <= lenPhon + 3; L++) {
    const g = pronti.perPhon.get(L);
    if (!g) continue;
    for (const p of g) if (!visti.has(p)) { visti.add(p); fuori.push(p); }
  }
  return fuori;
}

function scoreCandidatePronto(normInput, phoneInput, p) {
  const normC = p.norm;
  if (normInput === normC || normInput.replace(/ /g, '') === normC.replace(/ /g, '')) {
    return { dist: 0, method: 'exact', maxLen: Math.max(normInput.length, normC.length, 1) };
  }
  const dLen = Math.abs(normInput.length - normC.length);
  const dPhon = Math.abs(phoneInput.length - p.phon.length);
  const contenuto = normC.includes(normInput) || normInput.includes(normC);
  // scorciatoia: se non passa nessuna delle tre porte, nessun ramo potrebbe dare un match
  if (dLen > 4 && dPhon > 3 && !contenuto) return null;
  let best = null;
  if (dLen <= 4) {
    const dist = levenshtein(normInput, normC);
    const threshold = normInput.length <= 5 ? 2 : 3;
    if (dist <= threshold) best = { dist: dist, method: 'levenshtein' };
  }
  if (dPhon <= 3) {
    const pd = levenshtein(phoneInput, p.phon);
    if (pd <= 2 && (!best || pd < best.dist)) best = { dist: pd, method: 'phonetic' };
  }
  if (contenuto) {
    const cd = dLen;
    if (cd <= 5 && (!best || cd < best.dist)) best = { dist: cd, method: 'contains' };
  }
  if (best) best.maxLen = Math.max(normInput.length, normC.length, 1);
  return best;
}

function bestMatches(input, pronti) {
  const normInput = normalize(input);
  const phoneInput = phoneticIT(input);
  const scored = [];
  const lista = pronti.tutti ? candidatiPossibili(pronti, normInput.length, phoneInput.length) : pronti;
  for (const p of lista) {
    const s = scoreCandidatePronto(normInput, phoneInput, p);
    if (s) {
      const confidence = Math.round(Math.max(0, 1 - (s.dist / s.maxLen)) * 100) / 100;
      scored.push({ match: p.orig, confidence: confidence, method: s.method, _i: p.i });
    }
  }
  scored.sort(function (a, b) { return (b.confidence - a.confidence) || (a._i - b._i); });
  return scored.slice(0, 3).map(function (x) { return { match: x.match, confidence: x.confidence, method: x.method }; });
}

// retro-compatibilita': bestMatch singolo (usato altrove? no, ma sicuro)
function bestMatch(input, candidates) {
  const list = bestMatches(input, candidates);
  return list.length ? list[0] : null;
}

var AMB_GAP = 0.12; // due luoghi diversi entro 0.12 di confidence = ambiguo

function findEntities(text, candidates) {
  const pronti = preparaCandidati(candidates);
  const memo = new Map();
  const words = normalize(text).split(' ').filter(function (w) { return w.length >= 3; });
  const raw = [];
  for (let n = 3; n >= 1; n--) {
    for (let i = 0; i <= words.length - n; i++) {
      if (n === 1 && isCommonItalianWord(words[i])) continue; // anti-rumore ("volo"->"Vuoto")
      const phrase = words.slice(i, i + n).join(' ');
      let list = memo.get(phrase);
      if (list === undefined) { list = bestMatches(phrase, pronti); memo.set(phrase, list); }
      if (!list.length || list[0].confidence < 0.55) continue;
      raw.push({ start: i, end: i + n - 1, input: phrase, list: list });
    }
  }
  // ordina: confidence migliore prima; a parita', frase piu' lunga
  raw.sort(function (a, b) {
    return (b.list[0].confidence - a.list[0].confidence) || ((b.end - b.start) - (a.end - a.start));
  });
  const accepted = [];
  for (const r of raw) {
    const top = r.list[0];
    const overlap = accepted.find(function (a) { return !(r.end < a.start || r.start > a.end); });
    if (!overlap) {
      const alts = r.list.slice(1).filter(function (x) {
        return x.match !== top.match && x.confidence >= Math.max(0.55, top.confidence - AMB_GAP);
      });
      accepted.push({ start: r.start, end: r.end, input: r.input, top: top, alts: alts });
    } else {
      // frase sovrapposta che punta a un ALTRO luogo con punteggio vicino -> ambiguita'.
      // SOLO se la frase e' lunga almeno quanto quella accettata: una sotto-frase
      // ("torri" dentro "masseria torri", "cala ponte" dentro "cala ponte hotel")
      // e' rumore, non vera ambiguita'.
      if ((r.end - r.start) < (overlap.end - overlap.start)) continue;
      const known = [overlap.top.match].concat(overlap.alts.map(function (x) { return x.match; }));
      if (known.indexOf(top.match) === -1 && top.confidence >= Math.max(0.55, overlap.top.confidence - AMB_GAP)) {
        overlap.alts.push(top);
      }
    }
  }
  accepted.sort(function (a, b) { return a.start - b.start; });
  const results = [];
  for (const a of accepted) {
    // dedup alts per nome
    const seen = {};
    const alts = a.alts.filter(function (x) {
      if (seen[x.match]) return false;
      seen[x.match] = true;
      return x.match !== a.top.match;
    });
    if (alts.length) {
      const cands = [{ match: a.top.match, confidence: a.top.confidence, method: a.top.method }]
        .concat(alts.map(function (x) { return { match: x.match, confidence: x.confidence, method: x.method }; }))
        .sort(function (x, y) { return y.confidence - x.confidence; });
      results.push({
        input: a.input,
        match: null,
        ambiguous: true,
        candidates: cands,
        note: "AMBIGUO: piu' luoghi possibili con punteggi vicini. NON scegliere: CHIEDI all'utente quale intende, con bottoni."
      });
    } else {
      results.push({ input: a.input, match: a.top.match, confidence: a.top.confidence, method: a.top.method });
    }
  }
  return results;
}

const mergeData = $('Merge (all inputs)').first().json;
