function _lastCustomerMessage(t) {
  const text = String(t || '');
  const re = /\[\d{1,2}\/\d{1,2}\/\d{2,4},\s*\d{1,2}:\d{2}(?::\d{2})?\]\s*(~?)([^:\n]+?):\s*([\s\S]*?)(?=\n\[\d{1,2}\/\d{1,2}\/\d{2,4},|$)/g;
  let lastCustomer = '';
  let m;
  while ((m = re.exec(text)) !== null) {
    if (m[1] === '~') lastCustomer = m[3].trim();
  }
  return lastCustomer;
}

let inputText = _rawText;
const _lastCust = _lastCustomerMessage(_rawText);
if (_lastCust) {
