// ═══════════════════════════════════════════════════════════════
// SANITIZER RECAP GIORNALIERO
// ═══════════════════════════════════════════════════════════════
// Inserire come nodo Code TRA "AI Agent" e "Send a text message2"
// nella flow del Schedule Trigger.
//
// ⚠️ IMPORTANTE: nel nodo "Send a text message2" impostare:
//    Additional Fields → Parse Mode → HTML
// ═══════════════════════════════════════════════════════════════

let text = String(
  $input.first()?.json?.output ?? ""
)
  .replace(/\\n/g, "\n")
  .replace(/\u0000/g, "")
  .trim();

if (!text) text = "\u200B";

// ═══════════════════════════════════════════════════════════════
// STEP 1: Strip tag HTML dall'output agent (non dovrebbero esserci,
//         ma per sicurezza)
// ═══════════════════════════════════════════════════════════════
text = text.replace(/<\/?[a-zA-Z][^>]*>/g, "");

// ═══════════════════════════════════════════════════════════════
// STEP 2: Estrai URL e sostituisci con placeholder
//         Questo è il FIX CRITICO: gli underscore dentro gli URL
//         (es. ?g_st=iw) causano "can't parse entities" su Telegram
// ═══════════════════════════════════════════════════════════════
const urls = [];
text = text.replace(/https?:\/\/[^\s<>"')\]]+/g, (url) => {
  const idx = urls.length;
  // Rimuovi punteggiatura finale attaccata all'URL
  let clean = url.replace(/[.,;:!?)]+$/, "");
  let tail = url.slice(clean.length);
  urls.push({ url: clean, tail });
  return `\x00U${idx}\x00${tail}`;
});

// ═══════════════════════════════════════════════════════════════
// STEP 3: Escape entità HTML (& < >)
// ═══════════════════════════════════════════════════════════════
function esc(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

// Escape solo le parti di testo, NON i placeholder
text = text.split(/(\x00U\d+\x00)/).map(p =>
  /^\x00U\d+\x00$/.test(p) ? p : esc(p)
).join("");

// ═══════════════════════════════════════════════════════════════
// STEP 4: Converti markdown → HTML Telegram (se l'agent usa **bold**)
// ═══════════════════════════════════════════════════════════════
text = text.replace(/\*\*(.+?)\*\*/gs, "<b>$1</b>");
text = text.replace(/(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/gs, "<i>$1</i>");
text = text.replace(/__(.+?)__/gs, "<u>$1</u>");

// ═══════════════════════════════════════════════════════════════
// STEP 5: Ripristina URL come <a href="...">etichetta</a>
//         Dentro il tag <a>, underscore e punti sono sicuri
// ═══════════════════════════════════════════════════════════════
urls.forEach((item, i) => {
  const safeHref = item.url
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

  // Etichetta leggibile in base al dominio
  let label = "🔗 Link";
  if (item.url.includes("maps.app.goo.gl") || item.url.includes("google.com/maps")) {
    label = "📍 Mappa";
  } else if (item.url.includes("booking.com") || item.url.includes("guestreservations")) {
    label = "🏨 Hotel";
  }

  text = text.replace(`\x00U${i}\x00`, `<a href="${safeHref}">${label}</a>`);
});

// ═══════════════════════════════════════════════════════════════
// STEP 6: Pulizia virgolette tipografiche e caratteri speciali
//         Le smart quotes (" ") nei dati Google Sheets causano
//         problemi di parsing
// ═══════════════════════════════════════════════════════════════
text = text
  .replace(/[\u201C\u201D\u201E\u201F]/g, '"')   // " " „ ‟ → "
  .replace(/[\u2018\u2019\u201A\u201B]/g, "'")   // ' ' ‚ ‛ → '
  .replace(/[\u2013\u2014]/g, "-")                 // – — → -
  .replace(/\u2026/g, "...");                      // … → ...

// ═══════════════════════════════════════════════════════════════
// STEP 7: Safety net — rimuovi tag HTML non supportati da Telegram
// ═══════════════════════════════════════════════════════════════
const OK = new Set(["b", "i", "u", "s", "code", "pre", "a", "tg-spoiler"]);
text = text.replace(/<\/?([a-zA-Z][a-zA-Z0-9-]*)[^>]*>/g, (full, tag) =>
  OK.has(tag.toLowerCase()) ? full : ""
);

// ═══════════════════════════════════════════════════════════════
// STEP 8: Bilancia tag aperti/chiusi
// ═══════════════════════════════════════════════════════════════
for (const tag of ["b", "i", "u", "s", "code", "pre"]) {
  const opens  = (text.match(new RegExp(`<${tag}(\\s[^>]*)?>`, "g")) || []).length;
  const closes = (text.match(new RegExp(`</${tag}>`, "g")) || []).length;
  if (opens > closes) {
    for (let n = 0; n < opens - closes; n++) text += `</${tag}>`;
  } else if (closes > opens) {
    // Rimuovi i tag di chiusura in eccesso
    let excess = closes - opens;
    text = text.replace(new RegExp(`</${tag}>`, "g"), (m) => {
      if (excess > 0) { excess--; return ""; }
      return m;
    });
  }
}

// ═══════════════════════════════════════════════════════════════
// STEP 9: Limite 4096 caratteri Telegram
// ═══════════════════════════════════════════════════════════════
if (text.length > 4096) {
  let cut = text.substring(0, 4080);
  // SAFE CUT: non tagliare in mezzo a un tag HTML (es. <a href="...">).
  // Se dopo l'ultimo ">" c'e' un "<" senza il suo ">", tronca prima del "<".
  const lastOpen = cut.lastIndexOf("<");
  const lastClose = cut.lastIndexOf(">");
  if (lastOpen > lastClose) {
    cut = cut.substring(0, lastOpen);
  }
  text = cut + "\n\n[...troncato]";
  // Chiudi tag rimasti aperti dopo il troncamento
  for (const tag of ["b", "i", "u", "s", "code", "pre", "a"]) {
    const o = (text.match(new RegExp(`<${tag}[\\s>]`, "g")) || []).length;
    const c = (text.match(new RegExp(`</${tag}>`, "g")) || []).length;
    if (o > c) text += `</${tag}>`.repeat(o - c);
  }
}

// ═══════════════════════════════════════════════════════════════
// OUTPUT: passa il testo sanitizzato al nodo Send
// ═══════════════════════════════════════════════════════════════
return [{
  json: {
    output: text
  }
}];

// ============================================================================
// RISOLVI DATE DEL MESSAGGIO — 05/08/2026
// Il metodo indicato da Agostino: dal suo messaggio si estrae SOLO IL NUMERO della
// data, si cerca quel giorno nel calendario, e si verifica se combacia.
// Il risultato viene passato al modello GIÀ FATTO, prima che parli: così non deve
// indovinare niente e non c'è niente da correggere dopo.
// ============================================================================
function risolviDate(testoUtente, now) {
  const GIORNI = ['domenica', 'lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì', 'sabato'];
  const MESI = {
    gennaio: 1, febbraio: 2, marzo: 3, aprile: 4, maggio: 5, giugno: 6, luglio: 7,
    agosto: 8, settembre: 9, ottobre: 10, novembre: 11, dicembre: 12,
    gen: 1, feb: 2, mar: 3, apr: 4, mag: 5, giu: 6, lug: 7, ago: 8, set: 9, sett: 9, ott: 10, nov: 11, dic: 12
  };
  const WD = {
    domenica: 0, lunedi: 1, martedi: 2, mercoledi: 3, giovedi: 4, venerdi: 5, sabato: 6,
    dom: 0, lun: 1, mar: 2, mer: 3, gio: 4, ven: 5, sab: 6
  };
  const pad = (n) => String(n).padStart(2, '0');
  const strip = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const wdOf = (y, mo, d) => new Date(Date.UTC(y, mo - 1, d, 12)).getUTCDay();
  const esiste = (y, mo, d) => {
    if (!(y >= 1970 && y <= 2100 && mo >= 1 && mo <= 12 && d >= 1 && d <= 31)) return false;
    const t = new Date(Date.UTC(y, mo - 1, d, 12));
    return t.getUTCFullYear() === y && t.getUTCMonth() + 1 === mo && t.getUTCDate() === d;
  };
  const oggiMs = Date.UTC(now.y, now.mo - 1, now.d, 12);
  // anno assente: l'occorrenza più vicina a oggi, con preferenza per il futuro
  const anno = (d, mo, yy) => {
    if (yy) return yy < 100 ? yy + 2000 : yy;
    let sc = null, best = Infinity;
    for (const y of [now.y - 1, now.y, now.y + 1]) {
      if (!esiste(y, mo, d)) continue;
      const diff = Date.UTC(y, mo - 1, d, 12) - oggiMs;
      const p = diff >= 0 ? diff : (-diff + 1);
      if (p < best) { best = p; sc = y; }
    }
    return sc;
  };

  const t = strip(testoUtente);
  if (!t) return { date: [], blocco: '' };

  // ---- 1. i NUMERI delle date nel messaggio ----
  const trovate = [];
  const aggiungi = (d, mo, yy, comeScritto) => {
    const y = anno(d, mo, yy);
    if (y === null || !esiste(y, mo, d)) return;
    const iso = y + '-' + pad(mo) + '-' + pad(d);
    if (trovate.some(x => x.iso === iso)) return;
    trovate.push({ iso: iso, data: pad(d) + '/' + pad(mo) + '/' + y, giorno: GIORNI[wdOf(y, mo, d)],
                   wd: wdOf(y, mo, d), annoDedotto: !yy, comeScritto: comeScritto });
  };
  let m;
  // 2026-08-21
  const reIso = /(\d{4})-(\d{1,2})-(\d{1,2})/g;
  while ((m = reIso.exec(t))) aggiungi(+m[3], +m[2], +m[1], m[0]);
  const senzaIso = t.replace(reIso, '   ');
  // 21/08 · 21/08/2026 · 21.08.2026 (col punto serve l'anno: «21.30» è un orario)
  const reBarra = /(?<![\d.,:\/])(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?(?![\d\/])/g;
  while ((m = reBarra.exec(senzaIso))) aggiungi(+m[1], +m[2], m[3] ? +m[3] : null, m[0]);
  const rePunto = /(?<![\d.,:\/])(\d{1,2})\.(\d{1,2})\.(\d{2,4})(?!\d)/g;
  while ((m = rePunto.exec(senzaIso))) aggiungi(+m[1], +m[2], +m[3], m[0]);
  // 21 agosto 2026 · 21 ago 2026 · «29 e 30 agosto»
  const nomiMesi = Object.keys(MESI).sort((a, b) => b.length - a.length).join('|');
  const reParole = new RegExp('(?<![\\d.,:\\/])((?:\\d{1,2}\\s*(?:,|e|ed)\\s*)*\\d{1,2})\\s+(' + nomiMesi + ')(?![a-zà-ÿ])\\.?(?:\\s+(\\d{4}))?', 'g');
  while ((m = reParole.exec(senzaIso))) {
    const mo = MESI[m[2]];
    const yy = m[3] ? +m[3] : null;
    for (const n of (m[1].match(/\d{1,2}/g) || [])) aggiungi(+n, mo, yy, m[0]);
  }

  // ---- 2. i giorni della settimana che Agostino ha scritto ----
  const suoi = [];
  const reWd = new RegExp('(?<![a-zà-ÿ])(' + Object.keys(WD).sort((a, b) => b.length - a.length).join('|') + ')(?![a-zà-ÿ])', 'g');
  while ((m = reWd.exec(t))) {
    // «mar» subito dopo un numero di giorno è il mese marzo, non martedì
    if (m[1] === 'mar' && /\d[ \t]+$/.test(t.slice(0, m.index))) continue;
    const w = WD[m[1]];
    if (!suoi.some(x => x.wd === w)) suoi.push({ wd: w, scritto: m[1] });
  }

  if (!trovate.length) return { date: [], blocco: '' };

  // ---- 3. verifica del match e blocco pronto per il modello ----
  const righe = [];
  let discordanza = null;
  for (const x of trovate) {
    let esito = '';
    if (suoi.length === 1) {
      if (suoi[0].wd === x.wd) esito = ' ✅ COINCIDE con il giorno che ha scritto Agostino («' + suoi[0].scritto + '»)';
      else if (trovate.length === 1) {
        esito = ' ⚠️ Agostino ha scritto «' + suoi[0].scritto + '» ma quella data È ' + x.giorno;
        discordanza = { data: x.data, vero: x.giorno, scritto: suoi[0].scritto, wdScritto: suoi[0].wd };
      }
    }
    righe.push('• ' + x.data + ' = ' + x.giorno + (x.annoDedotto ? ' (anno dedotto: è l\'occorrenza più vicina)' : '') + esito);
  }

  // se il giorno indicato non coincide: quale data avrebbe quel giorno?
  let alternativa = null;
  if (discordanza) {
    const p = discordanza.data.split('/');
    const base = Date.UTC(+p[2], +p[1] - 1, +p[0], 12);
    let vicina = null, best = Infinity;
    for (let k = -7; k <= 7; k++) {
      const q = new Date(base + k * 86400000);
      if (q.getUTCDay() !== discordanza.wdScritto) continue;
      if (Math.abs(k) < best) { best = Math.abs(k); vicina = q; }
    }
    if (vicina) alternativa = pad(vicina.getUTCDate()) + '/' + pad(vicina.getUTCMonth() + 1) + '/' + vicina.getUTCFullYear();
  }

  const blocco = [
    '[DATE DEL MESSAGGIO DI AGOSTINO — GIÀ RISOLTE DAL CALENDARIO, NON RICALCOLARLE]',
    righe.join('\n'),
    discordanza
      ? ('⚠️ Il giorno che ha scritto NON coincide. Chiedi UNA sola volta, così: «Il ' + discordanza.data
         + ' è ' + discordanza.vero + ', non ' + discordanza.scritto + '. Intendi ' + discordanza.vero + ' ' + discordanza.data
         + (alternativa ? ' oppure ' + discordanza.scritto + ' ' + alternativa : '') + '?»'
         + (alternativa ? ' ⛔ Usa SOLO queste due date: sono le uniche verificate.' : ''))
      : '✅ Tutto coerente: NON fare domande sul giorno della settimana, procedi.',
    '⛔ Il giorno della settimana è quello scritto qui sopra. Non calcolarlo, non dedurlo, non contestarlo.'
  ].join('\n');

  return { date: trovate, suoi: suoi, discordanza: discordanza, alternativa: alternativa, blocco: blocco };
}

// ============================================================================
// «ORA» / «ADESSO» / «TRA VENTI MINUTI» — risolti prima che il modello parli
// 08/08/2026. Agostino ha dettato un transfer a voce, poi ha scritto «Ora», poi
// «Ora oggi»: il bot continuava a chiedere «dimmi a che ora è il transfer».
// Per lui «ora» era la risposta, non una parola vaga. Qui l'orario relativo viene
// calcolato dal codice, come già si fa per le date, e infilato nel contesto.
// Attenzione ai falsi: «ora» in italiano compare in «a che ora», «per ora»,
// «ancora», «ora che». Quelli NON contano.
// ============================================================================
function risolviOra(testoUtente, nowRoma) {
  const pad = (n) => String(n).padStart(2, '0');
  const strip = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
  const t = strip(testoUtente);
  if (!t) return { blocco: '' };

  const GIORNI = ['domenica', 'lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì', 'sabato'];
  const base = new Date(Date.UTC(nowRoma.y, nowRoma.mo - 1, nowRoma.d, nowRoma.h, nowRoma.mi));
  const quando = (minutiDopo) => {
    const q = new Date(base.getTime() + (minutiDopo || 0) * 60000);
    return {
      data: pad(q.getUTCDate()) + '/' + pad(q.getUTCMonth() + 1) + '/' + q.getUTCFullYear(),
      ora: pad(q.getUTCHours()) + ':' + pad(q.getUTCMinutes()),
      giorno: GIORNI[q.getUTCDay()],
      domani: q.getUTCDate() !== nowRoma.d
    };
  };

  // ---- «tra/fra X minuti | X ore | mezz'ora | un'ora» ----
  let minuti = null, scritto = '';
  const reTra = /\b(?:tra|fra|entro|in)\s+(un|una|uno|mezz|mezza|mezzo|\d{1,3})\s*'?\s*(minut\w*|min\b|or\w*|h\b)/;
  const mTra = t.match(reTra);
  if (mTra) {
    const q = mTra[1], u = mTra[2];
    const n = /^\d+$/.test(q) ? parseInt(q, 10) : (/^mezz/.test(q) ? 0.5 : 1);
    minuti = Math.round(/^or|^h/.test(u) ? n * 60 : n);
    scritto = mTra[0];
  }

  // ---- «ora / adesso / subito» ----
  if (minuti === null) {
    // «adesso» e «subito» sono inequivocabili
    const mSec = t.match(/\b(adesso|subito|immediatamente|al piu presto|appena possibile|asap)\b/);
    // «ora» conta solo se è la risposta secca alla domanda sull'orario:
    // messaggio corto, senza «a che ora», «per ora», «ora che», e non dentro «ancora»
    // «ora» vale come risposta secca («Ora», «Ora oggi») oppure come ULTIMA parola del
    // messaggio («…, 2 pax, ora», «il transfer è ora»). Non vale in «per ora», «a che ora»,
    // «un'ora», «quest'ora», «l'ora», «mezz'ora», «ancora».
    const secca = /^ora\b/.test(t) && t.split(/\s+/).length <= 3;
    const inCoda = /(?:^|[\s,;:])ora\s*[.!]*$/.test(t)
      && !/(?:per|che|quest|un|mezz|dell|all|l|d|da|fino ad|sull)'?\s*ora\s*[.!]*$/.test(t);
    const soloOra = secca || inCoda;
    const vietato = /\ba che ora\b|\bper ora\b|\bora che\b|\bancora\b|\bfino ad ora\b|\bda ora\b/.test(t);
    if (mSec && !vietato) { minuti = 0; scritto = mSec[1]; }
    else if (soloOra && !vietato) { minuti = 0; scritto = 'ora'; }
  }
  if (minuti === null) return { blocco: '' };

  const q = quando(minuti);
  const blocco = [
    '[QUANDO — GIÀ CALCOLATO DAL CODICE, NON RICHIEDERLO]',
    '• Agostino ha scritto «' + scritto + '»: adesso in Italia sono le '
      + quando(0).ora + ' di ' + quando(0).giorno + ' ' + quando(0).data + '.',
    '• Quindi il transfer è 📅 Data: ' + q.data + '  🕐 Ora: ' + q.ora
      + (minuti ? ' (' + quando(0).ora + ' + ' + minuti + ' minuti)' : ' (adesso)')
      + (q.domani ? ' — attenzione: cade dopo la mezzanotte, quindi il giorno dopo' : ''),
    '⛔ Data e ora sono queste: NON chiedergliele di nuovo. Se manca altro (pax, nome, cellulare,',
    'tariffa) chiedi SOLO quello che manca, una domanda sola.'
  ].join('\n');
  return { blocco: blocco, data: q.data, ora: q.ora, minuti: minuti, scritto: scritto };
}

// --- data risolta dal NUMERO, prima che il modello parli (05/08/2026) ---
var __oggiRoma = (function () {
  var d = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
  // ore e minuti servono a risolviOra: «ora», «adesso», «tra venti minuti»
