// Iniezione CRM Maps v2 — lookup inverso cellulare → nome (CRM)
const items = $input.all();
const cellMap = {};
const mailMap = {};
const phoneToName = {};
const phoneToMail = {};

function normalizePhone(raw) {
  if (!raw) return '';
  let p = String(raw).replace(/\D/g, '');
  if (p.startsWith('0039')) p = p.slice(4);
  else if (p.startsWith('39') && p.length >= 11) p = p.slice(2);
  if (p.startsWith('0') && p.length >= 10) p = p.slice(1);
  return p;
}

try {
  $('Clienti CRM').all().forEach(function(i) {
    const n = String(i.json['Nome'] || '').trim();
    const c = String(i.json['Cellulare'] || '').trim();
    const m = String(i.json['Mail'] || '').trim();
    // 11/08/2026: le mappe complete nome→cellulare/mail non servono più
    // (la rubrica è uscita dal contesto, c'è il tool cerca_cliente).
    if (c) {
      const norm = normalizePhone(c);
      if (norm && n) {
        phoneToName[norm] = n;
        if (m) phoneToMail[norm] = m;
      }
    }
  });
} catch (e) {}

function extractPhones(text) {
  if (!text) return [];
  const re = /(?:\+?\d[\d\s\-\.\/]{6,18}\d)/g;
  const out = [];
  const seen = new Set();
  let m;
  while ((m = re.exec(String(text))) !== null) {
    const norm = normalizePhone(m[0]);
    if (norm.length >= 9 && norm.length <= 13 && !seen.has(norm)) {
      seen.add(norm);
      out.push({ raw: m[0].trim(), normalized: norm });
    }
  }
  return out;
}

return items.map(function(it) {
  const text = String(it.json.text || it.json.original_text || it.json.clean_text || '');
  const phones = extractPhones(text);
  const phone_matches = phones.map(function(p) {
    const name = phoneToName[p.normalized] || '';
    const mail = phoneToMail[p.normalized] || '';
    return { raw: p.raw, normalized: p.normalized, name: name, mail: mail, found: !!name };
  });
  var __r = { blocco: '' };
  try { __r = risolviDate(String(it.json.original_text || it.json.text || ''), __oggiRoma); } catch (e) { __r = { blocco: '' }; }
  var __o = { blocco: '' };
  try { __o = risolviOra(String(it.json.original_text || it.json.text || ''), __oggiRoma); } catch (e) { __o = { blocco: '' }; }
  return { json: Object.assign({}, it.json, {
    cell_map: {},   // svuotata l'11/08/2026: usa il tool cerca_cliente
    mail_map: {},   // svuotata l'11/08/2026: usa il tool cerca_cliente
    phone_matches: phone_matches,
    date_risolte: [__r.blocco || '', __o.blocco || ''].filter(function (x) { return x; }).join('\n\n'),
    ora_relativa: __o.ora || '',
    date_risolte_dati: __r.date || []
  }) };
});

