function cleanId(s) {
  return String(s || '').replace(/<\/?code>/g, '').trim();
}
function empty(v) {
  return !v || v === '—' || v === '-' || String(v).toLowerCase() === 'da generare' || v === '' || String(v).trim() === '';
}
function fmtNum(v, suffix) {
  if (empty(v)) return '';
  const num = String(v).replace(/[€\s]/g, '').trim();
  if (!num || !/^\d/.test(num)) return '';
  return num + (suffix || '');
}
function getField(row, ...keys) {
  for (const k of keys) {
    if (row && row[k] !== undefined && row[k] !== null && String(row[k]).trim() !== '') {
      return String(row[k]).trim();
    }
  }
  return '';
