const FOREIGN_SURNAMES = /\b(smith|johnson|brown|williams|jones|miller|davis|garcia|martinez|wilson|anderson|taylor|moore|jackson|harris|clark|lewis|young|king|wright|scott|green|baker|nelson|carter|mitchell|roberts|phillips|campbell|parker|evans|edwards|collins|stewart|sanchez|morris|cook|morgan|murphy|cooper|peterson|ramirez|kelly|sanders|bennett|hughes|flores|gomez|murray|freeman|webb|hicks|crawford|black|daniels|palmer|knight|ferguson|stone|hawkins|spencer|matthews|arnold|wagner|olson|harper|fox|dubois|bernard|martin|petit|laurent|lefebvre|girard|moreau|simon|david|robin|nicolas|henry|lopez|hernandez|jimenez|ruiz|diaz|moreno|munoz|alvarez|romero|navarro|torres|dominguez|vasquez|ramos|gil|serrano|blanco|molina|suarez|ortega|delgado|castillo|medina|kim|park|lee|choi|cho|yoon|jang|han|shin|kwon|hwang|ahn|song|hong|wang|chen|zhang|liu|yang|huang|zhao|wu|zhou|xu|sun|hu|guo|gao|lin|wei|tang|nguyen|tran|le|pham|huynh|phan|vu|vo|dang|bui|ngo|patel|kumar|sharma|gupta|singh|das|mehta|jain|reddy|rao|iyer|nair|menon|hansen|jensen|nielsen|pedersen|larsen|sorensen|rasmussen|christensen|jorgensen|petersen|andersen|olsen|schmidt|muller|mueller|schneider|fischer|weber|wagner|becker|hoffmann|schulz|wolf|braun|klein|schwarz|jung|hahn|keller|huber|peters|lehmann|hartmann)\b/i;

// === DETECT LINGUA CLIENTE ===
// EN se: prefisso cell ≠ +39 OPPURE nome straniero (euristica)
function isForeign(nome, cell) {
  // Strategia: raccogli i segnali separatamente. Se ALMENO uno è "foreign", → EN.
  let cellForeign = false;
  if (cell) {
    const raw = String(cell).trim();
    const digits = raw.replace(/\D/g, '');
    if (digits.length >= 10) {
      const itPrefix = digits.startsWith('39');
      const itMobileNoPrefix = /^3\d{9}$/.test(digits);
      const itLandline = /^0\d{8,9}$/.test(digits);
      const hasPlus = /^\+/.test(raw);
      const tooLongNoIt = digits.length > 11 && !itPrefix;
      if (!itPrefix && !itMobileNoPrefix && !itLandline) {
        if (hasPlus || tooLongNoIt) cellForeign = true;
      }
    }
  }
  let nameForeign = false;
  if (nome) {
    const n = String(nome).toLowerCase().trim();
    if (n.length >= 2) {
      // Caratteri rari/assenti in italiano (KWXY, umlaut, slash nordici, accenti SP/PT/FR)
      if (/[kwxyñøåäöüíóáéúýçđł]/.test(n)) {
        nameForeign = true;
      // Terminazioni straniere tipiche (cognomi nordici/slavi/balcanici)
      } else if (/(son|sen|ski|stein|sky|berg|burg|escu|enko|ovich|ova\b|ová|skij)/i.test(n)) {
        nameForeign = true;
      // Cognomi anglo/iberi/asiatici/indiani frequenti
      } else if (FOREIGN_SURNAMES.test(n)) {
        nameForeign = true;
      // Terminazioni cognomi italiani molto comuni → IT
      } else if (/(ini|elli|etti|ucci|ozzi|ano|otti|ardo|otto|ello|esi|izzi|illo|ucca|usso|ietti|otta|olla|orio|asio|essi)\b/i.test(n)) {
        nameForeign = false;
      }
    }
  }
  return nameForeign || cellForeign;
}

