function renderFromRow(row, idx, total, isModifica) {
  const id = cleanId(getField(row, 'Id'));
  const data = getField(row, 'Data');
  const ora = getField(row, 'Ora', 'Time');
  const da = getField(row, 'Da', 'Transfer_Da', 'Transfer > Da');
  const per = getField(row, 'Per', 'Transfer_Per', 'Transfer < Per');
  const pax = getField(row, 'Pax');
  const nome = getField(row, 'Nome');
  const volo = getField(row, 'Volo');
  const fornitori = getField(row, 'Fornitori');
  const modalita = getField(row, 'Modalità', 'Modalita');
  const autista = getField(row, 'Autista');
  const veicolo = getField(row, 'Veicolo');
  const hextra = getField(row, 'h extra');
  const tariffa = getField(row, 'Tariffa');
  const acconto = getField(row, 'Acconto');
  const cell = getField(row, 'Cell.', 'Cell', 'Telefono');
  const note = getField(row, 'Note');

  const isMultiStop = /→.*→|›.*›/.test(per);
  const hasReturn = /rientro|ritorno|return/i.test((note || '') + ' ' + (per || ''));

  const lines = [];
  if (total > 1) {
    lines.push(L.bookN(idx + 1, total, isModifica));
  } else {
    lines.push(isModifica ? L.bookUpdate : L.bookConfirm);
  }
  lines.push('');

  if (!empty(data)) {
    let dateLine = '📅 ' + data;
    if (!empty(ora)) dateLine += L.at + ora;
    lines.push(dateLine);
  }
  if (!empty(da)) lines.push(L.from + da);
  if (!empty(per)) {
    const arrow = isMultiStop ? L.itinerary : L.to;
    let perLine = arrow + per;
    if (hasReturn && !isMultiStop && !/(rientro|ritorno|return)/i.test(per)) {
      const m = (note || '').match(/(?:rientro|ritorno|return)[^,;\n]*/i);
      if (m) perLine += ' (' + m[0].trim() + ')';
    }
    lines.push(perLine);
  }

  if (!empty(nome) && !empty(pax)) {
    lines.push('👤 ' + nome + ' (' + pax + ' ' + L.pax + ')');
  } else if (!empty(nome)) {
    lines.push('👤 ' + nome);
  } else if (!empty(pax)) {
    const word = pax === '1' ? L.passenger : L.passengers;
    lines.push('👥 ' + pax + ' ' + word);
  }

  if (!empty(cell)) lines.push('📞 ' + cell);
  if (!empty(fornitori)) lines.push('🏢 ' + fornitori);
  if (!empty(modalita)) lines.push(L.modalita + modalita);
  if (!empty(volo)) lines.push(L.flight + volo);
  if (!empty(autista)) lines.push(L.driver + autista);
  if (!empty(veicolo)) lines.push(L.vehicle + veicolo);
  if (!empty(hextra)) lines.push(L.hextra + hextra);

  const tariffaNum = parseFloat(String(tariffa).replace(/[€\s]/g, '').replace(',', '.'));
  const tariffaFmt = fmtNum(tariffa, '€');
  const isOmaggio = /omaggio|gratis|gratuit|free/i.test(modalita || '');
  if (tariffaFmt && tariffaNum > 0) {
    lines.push(L.fare + tariffaFmt);
  } else if (isOmaggio) {
    lines.push(L.fare + (useEN ? 'Free' : 'Omaggio'));
  } else {
    lines.push(L.fare + (useEN ? '⚠️ TO BE DEFINED' : '⚠️ DA DEFINIRE'));
  }
  const accontoFmt = fmtNum(acconto, '€');
  if (accontoFmt) lines.push(L.deposit + accontoFmt);

  if (!empty(note)) lines.push(L.notes + note);

  if (!empty(id)) {
    lines.push('');
    lines.push('<i>' + L.bookingCode + '</i> <code>' + id + '</code>');
  }
  return lines.join('\n');
}

