const MAX_LEN = 3800;

function splitIntoChunks(text, maxLen) {
  if (STA(text, maxLen)) return [text];
  const sep = '\n\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\n';
  const pezzi = [];
  for (const p of String(text).split(sep)) {
    for (const q of p.split(/(?=\n\n)/)) pezzi.push(q);
  }
  const chunks = [];
  for (const p of pezzi) {
    const u = chunks.length - 1;
    const cucito = u >= 0 ? chunks[u] + p : p;
    if (u >= 0 && STA(cucito, maxLen)) { chunks[u] = cucito; continue; }
    if (STA(p, maxLen)) { chunks.push(p); continue; }
    // pezzo singolo troppo lungo (nessun link dentro): si taglia sui caratteri visibili
    let resto = p;
    while (VIS(resto).length > (maxLen || 3800)) {
      let taglio = Math.floor((maxLen || 3800) * 0.95);
      let a = resto.slice(0, taglio);
      const ultimo = a.lastIndexOf('\n');
      if (ultimo > 200) a = a.slice(0, ultimo);
      chunks.push(a);
      resto = resto.slice(a.length);
    }
    if (resto.trim()) chunks.push(resto);
  }
  return chunks.filter((c) => c && c.trim());
}



// === TRE MESSAGGI SCRITTI DAL CODICE (07/08/2026) ===
// Cliente (IT/EN), fornitore (IT), autista (IT): non più il recap fotocopiato per tutti,
// ma tre testi diversi composti dai campi della riga salvata sul gestionale.
// === QUANTO È LUNGO UN MESSAGGIO PER TELEGRAM (07/08/2026) ===
// Provato sul campo con il bot: Telegram conta i caratteri CHE SI VEDONO, non gli indirizzi
// dentro i link. Un messaggio da 9.317 caratteri grezzi con 3 link passa; uno da 12.258 con
// 4 link viene rifiutato con ENTITIES_TOO_LONG. Quindi i limiti veri sono due:
//   • 4096 caratteri visibili
//   • circa 10 KB di indirizzi nei link (10240 byte, ~50 di contorno per ogni link)
// Prima si misurava il testo GREZZO: un recap con 5 link precompilati (che dentro l'URL si
// portano tutto il messaggio per cliente, fornitore e autista) sfondava i 3800 subito e
// Agostino si ritrovava 5-6 messaggi di seguito per un solo salvataggio.
const VIS = (s) => String(s === undefined || s === null ? '' : s)
  .replace(/<a\s+href="[^"]*">/gi, '').replace(/<\/?[a-z][^>]*>/gi, '');
const PESO_LINK = (s) => {
  let n = 0, m; const re = /<a\s+href="([^"]*)"/gi;
  while ((m = re.exec(String(s === undefined || s === null ? '' : s)))) n += m[1].length + 64;
  return n;
};
const TETTO_VIS = 3800, TETTO_LINK = 9500;
const STA = (s, maxVis) => VIS(s).length <= (maxVis || TETTO_VIS) && PESO_LINK(s) <= TETTO_LINK;

// ============================================================================
// COMPONI MESSAGGI — 07/08/2026
// Un solo motore che, dai DATI del transfer (le righe salvate sul gestionale, o
// la scheda della bozza), scrive i tre messaggi in chiaro:
//   • CLIENTE   (italiano o inglese secondo il numero/nome) — cortese, con policy
//   • FORNITORE (sempre italiano) — riepilogo operativo per la struttura
//   • AUTISTA   (sempre italiano) — solo cosa gli serve per lavorare, e se incassare
// Niente testo scopiazzato dal recap: ogni messaggio nasce dai campi.
// Restituisce anche i link wa.me già pronti, in ordine: cliente, fornitore, autista.
// ============================================================================
function componiMessaggi(righeIn, ana) {
  ana = ana || {};
  const fornCell = ana.fornitori || {};   // {'nome fornitore': '3331234567'}
  const autCell = ana.autisti || {};      // {'nome autista': '3331234567'}

  // ---------- utilità ----------
  const vuoto = (v) => v === undefined || v === null || String(v).trim() === '' ||
    ['—', '-', 'n/d', 'da generare', 'da assegnare'].includes(String(v).trim().toLowerCase());
  const S = (v) => vuoto(v) ? '' : String(v).trim();
  const campo = (r, ...k) => { for (const x of k) { const v = S(r && r[x]); if (v) return v; } return ''; };
  const tel = (raw) => {
    let d = String(raw == null ? '' : raw).replace(/[^0-9]/g, '');
    if (!d) return null;
    if (d.startsWith('00')) d = d.slice(2);
    if (d.length === 10 && d[0] === '3') d = '39' + d;
    return d.length >= 8 ? d : null;
  };
  const soldi = (v) => { const n = String(v == null ? '' : v).replace(/[^\d,.]/g, '').replace(',', '.'); if (!n || isNaN(Number(n))) return ''; const x = Number(n); return (Math.round(x * 100) / 100).toString().replace('.', ',') + '€'; };
  const idPulito = (v) => S(v).replace(/<\/?code>/g, '');
  const maps = (luogo) => { const l = S(luogo); if (!l) return ''; const h = l.match(/https?:\/\/\S+/); return h ? h[0] : 'https://www.google.com/maps?q=' + encodeURIComponent(l); };

  // data leggibile: accetta «dom 6 settembre 2026», «06/09/2026», «2026-09-06»
  const GIORNI = ['domenica', 'lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì', 'sabato'];
  const GIORNI_EN = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const MESI = ['gennaio', 'febbraio', 'marzo', 'aprile', 'maggio', 'giugno', 'luglio', 'agosto', 'settembre', 'ottobre', 'novembre', 'dicembre'];
  const MESI_EN = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const ABBR = { gen: 1, feb: 2, mar: 3, apr: 4, mag: 5, giu: 6, lug: 7, ago: 8, set: 9, sett: 9, ott: 10, nov: 11, dic: 12 };
  function pezziData(v) {
    const t = S(v).toLowerCase();
    if (!t) return null;
    let m = t.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
    if (m) return { y: +m[1], mo: +m[2], d: +m[3] };
    m = t.match(/(\d{1,2})[\/.](\d{1,2})[\/.](\d{2,4})/);
    if (m) return { y: +m[3] < 100 ? +m[3] + 2000 : +m[3], mo: +m[2], d: +m[1] };
    m = t.match(/(\d{1,2})\s+([a-zà-ÿ]+)\.?\s*(\d{4})?/);
    if (m) {
      const nome = m[2];
      let mo = MESI.indexOf(nome) + 1;
      if (!mo) mo = ABBR[nome.slice(0, 4)] || ABBR[nome.slice(0, 3)] || 0;
      if (mo) return { y: m[3] ? +m[3] : new Date().getFullYear(), mo: mo, d: +m[1] };
    }
    return null;
  }
  function dataScritta(v, en) {
    const p = pezziData(v);
    if (!p) return S(v);
    const wd = new Date(Date.UTC(p.y, p.mo - 1, p.d, 12)).getUTCDay();
    return en
      ? GIORNI_EN[wd] + ' ' + p.d + ' ' + MESI_EN[p.mo - 1] + ' ' + p.y
      : GIORNI[wd] + ' ' + p.d + ' ' + MESI[p.mo - 1] + ' ' + p.y;
  }
  const ordinabile = (r) => {
    const p = pezziData(r.data);
    const o = (r.ora.match(/(\d{1,2}):(\d{2})/) || [0, 0, 0]);
    return (p ? p.y * 10000 + p.mo * 100 + p.d : 0) * 10000 + (+o[1] || 0) * 100 + (+o[2] || 0);
  };

  const AEROPORTO = /aeroport|airport|stazione|station|porto\b|molo\b/i;
  // chi tiene i soldi: l'autista incassa SOLO se la modalità dice «incassare» o «contanti»
  const DA_INCASSARE = /incassar|contant|carta a bordo|pos/i;
  const GIA_PAGATO = /fattur|pagat|bonific|link|sumup|paypal|acconto\s*100|prepagat/i;

  // ---------- normalizzazione delle righe in ingresso ----------
  // L'ereditarietà di numero e nome (andata/ritorno dove il secondo blocco non li ripete)
  // vale SOLO tra righe dello STESSO fornitore e con nome compatibile: altrimenti il numero
  // di un cliente finirebbe sul transfer di un altro. Guasto trovato il 07/08/2026 provando
  // il rientro Julia Acquavita + la bozza Dimora Brando nello stesso messaggio.
  let prec = null;
  const righe = (righeIn || []).map((r) => {
    const o = {
      data: campo(r, 'Data', 'data'),
      ora: campo(r, 'Time', 'Ora', 'ora'),
      da: campo(r, 'Transfer > Da', 'Da', 'Transfer_Da', 'da'),
      per: campo(r, 'Transfer < Per', 'Per', 'Transfer_Per', 'per'),
      pax: campo(r, 'Pax', 'pax'),
      nome: campo(r, 'Nome', 'nome'),
      cell: campo(r, 'Cell.', 'Cell', 'Telefono', 'cell'),
      volo: campo(r, 'Volo', 'Flight', 'volo'),
      veicolo: campo(r, 'Veicolo', 'veicolo'),
      autista: campo(r, 'Autista', 'autista'),
      fornitore: campo(r, 'Fornitori', 'Fornitore', 'fornitori'),
      modalita: campo(r, 'Modalità', 'Modalita', 'modalita'),
      tariffa: campo(r, 'Tariffa', 'tariffa'),
      note: campo(r, 'Note', 'note'),
      id: idPulito(campo(r, 'Id', 'TR-Id', 'id'))
    };
    const stessoFornitore = prec && prec.fornitore && o.fornitore &&
      prec.fornitore.toLowerCase() === o.fornitore.toLowerCase();
    const nomiCompatibili = !prec || !o.nome || !prec.nome ||
      o.nome.toLowerCase() === prec.nome.toLowerCase();
    if (stessoFornitore && nomiCompatibili) {
      if (!o.cell) o.cell = prec.cell;
      if (!o.nome) o.nome = prec.nome;
    }
    prec = o;
    return o;
  }).filter((o) => o.data || o.ora || o.da || o.per);
  righe.sort((a, b) => ordinabile(a) - ordinabile(b));

  // ---------- lingua del cliente ----------
  const straniero = (r) => {
    const t = tel(r.cell);
    if (t) return !t.startsWith('39');
    return false;   // senza numero: parliamo italiano
  };

  // ---------- POLICY (identica a quella già in uso) ----------
  const POL = {
    it: (partenza, arrivo) => {
      const p = ['', 'ℹ️ Policy cancellazione e ritardi:',
        '• Ritardo cliente fino a 1h: attesa gratuita. Oltre 1h: soggetto a disponibilità + supplementi.'];
      if (partenza) p.push('• Transfer in partenza: ti consigliamo di essere pronto all\'orario indicato.');
      if (arrivo) p.push('• Transfer aeroporto: comunica in anticipo eventuali ritardi del volo — no-show senza preavviso = trattenuta acconto 50%.');
      p.push('• Cancellazione oltre 48h prima: rimborso pieno. 24–48h: trattenuto 50% acconto. Entro 24h o no-show: trattenuto 100%.');
      return p.join('\n');
    },
    en: (partenza, arrivo) => {
      const p = ['', 'ℹ️ Cancellation & delay policy:',
        '• Client delay up to 1h: free wait. Beyond 1h: subject to availability + supplements.'];
      if (partenza) p.push('• Departure transfers: please be ready at the agreed time.');
      if (arrivo) p.push('• Airport transfers: please notify any flight delay in advance — no-show without notice forfeits the 50% deposit.');
      p.push('• Cancellations over 48h before: full refund. 24–48h: 50% deposit retained. Within 24h or no-show: 100% retained.');
      return p.join('\n');
    }
  };

  // ---------- il blocco di UN transfer, per ciascun destinatario ----------
  function bloccoCliente(r, en) {
    const L = en
      ? { da: 'From', per: 'To', pax: 'passengers', volo: 'Flight', tar: 'Fare', rif: 'Ref' }
      : { da: 'Da', per: 'A', pax: 'passeggeri', volo: 'Volo', tar: 'Tariffa', rif: 'Rif' };
    const o = [];
    o.push('📅 ' + dataScritta(r.data, en) + (r.ora ? (en ? ' at ' : ' · ore ') + r.ora : ''));
    if (r.da) o.push('📍 ' + L.da + ': ' + r.da);
    if (r.per) o.push('🎯 ' + L.per + ': ' + r.per);
    if (r.pax) o.push('👥 ' + r.pax + ' ' + L.pax);
    if (r.volo) o.push('✈️ ' + L.volo + ': ' + r.volo);
    const t = soldi(r.tariffa);
    if (t) {
      const nota = DA_INCASSARE.test(r.modalita) ? (en ? ' (to be paid to the driver)' : ' (da saldare all\'autista)')
        : GIA_PAGATO.test(r.modalita) ? (en ? ' (already settled)' : ' (già regolata)') : '';
      o.push('💰 ' + L.tar + ': ' + t + nota);
    }
    if (r.id) o.push('🆔 ' + L.rif + ': ' + r.id);
    return o.join('\n');
  }
  function bloccoFornitore(r) {
    const o = [];
    o.push('📅 ' + dataScritta(r.data, false) + (r.ora ? ' · ore ' + r.ora : ''));
    if (r.nome || r.pax) o.push('👤 ' + [r.nome, r.pax ? r.pax + ' pax' : ''].filter(Boolean).join(' · '));
    if (r.da) o.push('📍 Da: ' + r.da);
    if (r.per) o.push('🎯 A: ' + r.per);
    if (r.volo) o.push('✈️ Volo: ' + r.volo);
    if (r.modalita) o.push('💳 Modalità: ' + r.modalita);
    const t = soldi(r.tariffa);
    if (t) o.push('💰 Tariffa: ' + t);
    if (r.id) o.push('🆔 Rif: ' + r.id);
    return o.join('\n');
  }
  function bloccoAutista(r) {
    const o = [];
    o.push('📅 ' + dataScritta(r.data, false) + (r.ora ? ' · ore ' + r.ora : ''));
    if (r.da) o.push('📍 Ritiro: ' + r.da + (maps(r.da) ? ' → ' + maps(r.da) : ''));
    if (r.per) o.push('🎯 Destinazione: ' + r.per + (maps(r.per) ? ' → ' + maps(r.per) : ''));
    const chi = [r.nome, r.pax ? r.pax + ' pax' : ''].filter(Boolean).join(' · ');
    if (chi) o.push('👤 ' + chi);
    const t = tel(r.cell);
    if (t) o.push('📞 Cliente: +' + t);
    if (r.volo) o.push('✈️ Volo: ' + r.volo);
    if (r.veicolo) o.push('🚗 Veicolo: ' + r.veicolo);
    const tar = soldi(r.tariffa);
    if (DA_INCASSARE.test(r.modalita) && tar) o.push('💵 Da incassare: ' + tar + ' (' + r.modalita + ')');
    else if (r.modalita) o.push('✅ Non incassare nulla: ' + r.modalita);
    if (r.note) o.push('📝 ' + r.note);
    if (r.id) o.push('🆔 Rif: ' + r.id);
    return o.join('\n');
  }

  // ---------- raggruppa per destinatario ----------
  // 07/08/2026 (Agostino): il link si fa ANCHE senza numero — wa.me senza numero apre
  // WhatsApp col testo già scritto e lascia scegliere il contatto a mano.
  const gruppi = { cliente: new Map(), fornitore: new Map(), autista: new Map() };
  // senza numero il gruppo si tiene insieme per NOME; se manca anche il nome, per fornitore
  // (andata/ritorno della stessa struttura); se manca tutto, un link per transfer — mai
  // mescolare due clienti diversi nello stesso messaggio.
  const aggiungi = (dove, t, nome, extra, r) => {
    const k = t ? ('tel:' + t)
      : nome ? ('nome:' + String(nome).toLowerCase())
        : r.fornitore ? ('forn:' + r.fornitore.toLowerCase())
          : ('id:' + (r.id || Math.abs(righe.indexOf(r))));
    if (!gruppi[dove].has(k)) gruppi[dove].set(k, Object.assign({ tel: t, nome: nome, righe: [] }, extra || {}));
    gruppi[dove].get(k).righe.push(r);
  };
  for (const r of righe) {
    aggiungi('cliente', tel(r.cell), r.nome, { en: straniero(r) }, r);
    // noi non ci mandiamo messaggi da soli
    const NOI = /^(transfer\s*experience|transferexperience|te)$/i;
    if (r.fornitore && !NOI.test(r.fornitore.trim())) aggiungi('fornitore', tel(fornCell[r.fornitore.toLowerCase()]), r.fornitore, null, r);
    if (r.autista) {
      const nomeAut = /^(—|-|n\/d|da assegnare|nessuno)$/i.test(r.autista.trim()) ? '' : r.autista;
      if (nomeAut) aggiungi('autista', telAutista(r.autista, autCell, tel), nomeAut, null, r);
    }
  }

  // ---------- i messaggi completi ----------
  const messaggi = [];
  for (const g of gruppi.cliente.values()) {
    const en = g.en;
    const partenza = g.righe.some((r) => AEROPORTO.test(r.per));
    const arrivo = g.righe.some((r) => AEROPORTO.test(r.da));
    const uno = g.righe.length === 1;
    const apertura = en
      ? (g.nome ? 'Dear ' + g.nome + ',' : 'Hello,') + '\n' + (uno ? 'your transfer with Transfer Experience is confirmed 🚐' : 'your ' + g.righe.length + ' transfers with Transfer Experience are confirmed 🚐')
      : (g.nome ? 'Gentile ' + g.nome + ',' : 'Buongiorno,') + '\n' + (uno ? 'il suo transfer con Transfer Experience è confermato 🚐' : 'i suoi ' + g.righe.length + ' transfer con Transfer Experience sono confermati 🚐');
    const corpo = g.righe.map((r, i) => (uno ? '' : (en ? '— Transfer ' + (i + 1) + ' —\n' : '— Transfer ' + (i + 1) + ' —\n')) + bloccoCliente(r, en)).join('\n\n');
    const chiusura = en
      ? '\nFor any change we are at your disposal. Thank you!'
      : '\nPer qualsiasi modifica siamo a disposizione. Grazie!';
    messaggi.push({ tipo: 'cliente', tel: g.tel, nome: g.nome, lingua: en ? 'en' : 'it',
      testo: [apertura, '', corpo, (en ? POL.en : POL.it)(partenza, arrivo), chiusura].join('\n'),
      senzaPolicy: [apertura, '', corpo, chiusura].join('\n') });
  }
  for (const g of gruppi.fornitore.values()) {
    const uno = g.righe.length === 1;
    const apertura = 'Buongiorno,\n' + (uno ? 'riepilogo del transfer prenotato:' : 'riepilogo dei ' + g.righe.length + ' transfer prenotati:');
    const corpo = g.righe.map((r, i) => (uno ? '' : '— Transfer ' + (i + 1) + ' —\n') + bloccoFornitore(r)).join('\n\n');
    messaggi.push({ tipo: 'fornitore', tel: g.tel, nome: g.nome, lingua: 'it',
      testo: [apertura, '', corpo, '', 'Per qualsiasi variazione scriveteci. Grazie!'].join('\n') });
  }
  for (const g of gruppi.autista.values()) {
    const uno = g.righe.length === 1;
    const nome1 = String(g.nome || '').trim().split(/\s+/)[0];
    const apertura = 'Ciao' + (nome1 ? ' ' + nome1 : '') + ', ' + (uno ? 'servizio assegnato 🚗' : g.righe.length + ' servizi assegnati 🚗');
    const corpo = g.righe.map((r, i) => (uno ? '' : '— Servizio ' + (i + 1) + ' —\n') + bloccoAutista(r)).join('\n\n');
    messaggi.push({ tipo: 'autista', tel: g.tel, nome: g.nome, lingua: 'it',
      testo: [apertura, '', corpo, '', 'Confermami che l\'hai visto. Grazie!'].join('\n') });
  }

  // ---------- link Telegram, in ordine ----------
  const ordine = { cliente: 0, fornitore: 1, autista: 2 };
  const piuClienti = gruppi.cliente.size > 1;
  // il nome arriva da un foglio: se contiene & < > o un ritorno a capo rompe l'HTML di Telegram
  const esc = (v) => String(v == null ? '' : v).replace(/[\r\n]+/g, ' ')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').trim();
  const etichetta = (m) => {
    const coda = m.tel ? ' su WhatsApp' : ' su WhatsApp (scegli tu il contatto)';
    if (m.tipo === 'cliente') {
      const chi = (piuClienti && m.nome) ? ' a ' + esc(m.nome) : ' al cliente';
      return '💬 Invia messaggio' + chi + coda;
    }
    if (m.tipo === 'fornitore') return '🏢 Invia messaggio al fornitore (' + esc(m.nome) + ')' + coda;
    return '🚗 Invia messaggio all’autista (' + esc(m.nome) + ')' + coda;
  };
  // Telegram rifiuta i messaggi oltre 4096 caratteri e il link ci sta DENTRO al messaggio:
  // se il testo precompilato è troppo lungo si accorcia da solo, prima la policy, poi le tratte.
  const TETTO = 3000;   // caratteri del link, non del testo
  const link = (m) => {
    let t = m.testo;
    const base = 'https://wa.me/' + (m.tel || '') + '?text=';
    let url = base + encodeURIComponent(t);
    if (url.length <= TETTO) return url;
    if (m.senzaPolicy) { t = m.senzaPolicy; url = base + encodeURIComponent(t); }
    if (url.length <= TETTO) return url;
    // ancora troppo: taglia sulle tratte, ma dillo
    const coda = m.lingua === 'en' ? '\n\n…full details in the confirmation.' : '\n\n…il resto nel messaggio di conferma.';
    let taglio = t;
    while ((base + encodeURIComponent(taglio + coda)).length > TETTO && taglio.length > 200) {
      taglio = taglio.slice(0, Math.floor(taglio.length * 0.85));
      const ultimo = taglio.lastIndexOf('\n\n');
      if (ultimo > 200) taglio = taglio.slice(0, ultimo);
    }
    return base + encodeURIComponent(taglio + coda);
  };
  let html = messaggi.slice().sort((a, b) => (ordine[a.tipo] - ordine[b.tipo]) || ((b.tel ? 1 : 0) - (a.tel ? 1 : 0)))
    .map((m) => '<a href="' + link(m) + '">' + etichetta(m) + '</a>').join('\n');
  // 07/08/2026 (Agostino): un link finale SENZA numero, per rimandare gli stessi servizi
  // a chi vuole lui — sceglie il contatto dentro WhatsApp.
  if (righe.length) {
    const uno = righe.length === 1;
    const corpo = righe.map((r, i) => (uno ? '' : '— Transfer ' + (i + 1) + ' —\n') + bloccoFornitore(r)).join('\n\n');
    const libero = ['Buongiorno,', (uno ? 'riepilogo del transfer:' : 'riepilogo dei ' + righe.length + ' transfer:'), '', corpo].join('\n');
    // ⛔ si taglia sull'URL CODIFICATO, non sul testo: 2500 caratteri di testo con emoji e
    // ritorni a capo diventavano oltre 7000 caratteri di URL e Telegram rifiutava il
    // messaggio (limite 4096). Con 8 e 12 transfer il banco lo dimostrava.
    const b0 = 'https://wa.me/?text=';
    let t0 = libero, url = b0 + encodeURIComponent(t0);
    if (url.length > TETTO) {
      const coda0 = '\n\n…il resto nei link qui sopra.';
      while ((b0 + encodeURIComponent(t0 + coda0)).length > TETTO && t0.length > 200) {
        t0 = t0.slice(0, Math.floor(t0.length * 0.85));
        const u0 = t0.lastIndexOf('\n\n');
        if (u0 > 200) t0 = t0.slice(0, u0);
      }
      url = b0 + encodeURIComponent(t0 + coda0);
    }
    html += (html ? '\n' : '') + '<a href="' + url + '">📲 Manda questi servizi a un altro contatto (scegli tu)</a>';
  }

  // 07/08/2026 (Agostino): «link per recensione, link per tutto, così posso introdurre una
  // conversazione». Pronto da mandare A SERVIZIO CONCLUSO: non è parte della conferma.
  {
    const REC = {
      en: 'We hope you enjoyed your experience with Transfer Experience! Your feedback means the world to us — leave a review on our profile and help others discover unforgettable service! https://g.page/r/CSZur2xwSkJFEBE/review',
      it: 'Speriamo che il viaggio con Transfer Experience sia stato all’altezza! Un tuo parere per noi vale molto: lasciaci una recensione e aiuta altri a scegliere bene. https://g.page/r/CSZur2xwSkJFEBE/review'
    };
    const clienti = messaggi.filter((m) => m.tipo === 'cliente');
    if (clienti.length && clienti.length <= 3) {
      for (const c of clienti) {
        const t = REC[c.lingua === 'en' ? 'en' : 'it'];
        const chi = (clienti.length > 1 && c.nome) ? ' a ' + esc(c.nome) : '';
        const coda = c.tel ? '' : ' (scegli tu il contatto)';
        html += (html ? '\n' : '') + '<a href="https://wa.me/' + (c.tel || '') + '?text='
          + encodeURIComponent(t) + '">⭐ Chiedi la recensione' + chi + coda + '</a>';
      }
    } else if (clienti.length) {
      html += (html ? '\n' : '') + '<a href="https://wa.me/?text=' + encodeURIComponent(REC.it)
        + '">⭐ Chiedi la recensione (scegli tu il contatto)</a>';
    }
  }

  // ⛔ NIENTE DOPPIONI (08/08/2026, «attento ai doppioni»): due link con lo STESSO indirizzo
  // sono lo stesso messaggio allo stesso numero. Capita quando il cliente e il contatto del
  // fornitore sono la stessa persona, o quando la stessa riga arriva due volte dal foglio.
  {
    const visti = new Set(), tenute = [];
    for (const riga of html.split('\n')) {
      const m = riga.match(/href="([^"]+)"/);
      const k = m ? m[1] : riga;
      if (visti.has(k)) continue;
      visti.add(k);
      tenute.push(riga);
    }
    html = tenute.join('\n');
  }

  return { righe: righe, messaggi: messaggi.map((m) => Object.assign({}, m, { link: link(m), etichetta: etichetta(m) })), links: html };
}

// nome autista → numero, con match su nome/cognome parziale ma MAI ambiguo
function telAutista(nome, autCell, tel) {
  const q = String(nome || '').trim().toLowerCase().replace(/\s+/g, ' ');
  if (!q || /^(—|-|n\/d|da assegnare|nessuno)$/.test(q)) return null;
  if (autCell[q]) return tel(autCell[q]);
  const qt = q.split(' ').filter(Boolean);
  let scelto = null, quanti = 0;
  for (const k of Object.keys(autCell)) {
    const kt = k.split(/\s+/);
    const corto = qt.length <= kt.length ? qt : kt;
    const lungo = qt.length <= kt.length ? kt : qt;
    if (corto.every((t) => lungo.some((u) => u === t || u.startsWith(t)))) { scelto = k; quanti++; }
  }
  return quanti === 1 ? tel(autCell[scelto]) : null;
}

// Da TESTO di scheda (bozza/recap) a righe strutturate: serve quando i dati non sono
// ancora sul foglio (bozze). Le etichette sono quelle usate dai recap, IT e EN.
function righeDaTesto(testo) {
  const ETI = [
    ['Data', /^[^\p{L}\n]*\s*(?:Data|Date)\s*:\s*(.+)$/iu],
    ['Time', /^[^\p{L}\n]*\s*(?:Ora|Time)\s*:\s*(.+)$/iu],
    ['Da', /^[^\p{L}\n]*\s*(?:Da|From)\s*:\s*(.+)$/iu],
    ['Per', /^[^\p{L}\n]*\s*(?:Per|To|A)\s*:\s*(.+)$/iu],
    ['Pax', /^[^\p{L}\n]*\s*Pax\s*:\s*(.+)$/iu],
    ['Nome', /^[^\p{L}\n]*\s*(?:Nome|Name)\s*:\s*(.+)$/iu],
    ['Cell.', /^[^\p{L}\n]*\s*(?:Cell\.?|Phone|Telefono)\s*:\s*(.+)$/iu],
    ['Volo', /^[^\p{L}\n]*\s*(?:Volo|Flight)\s*:\s*(.+)$/iu],
    ['Veicolo', /^[^\p{L}\n]*\s*(?:Veicolo|Vehicle)\s*:\s*(.+)$/iu],
    ['Autista', /^[^\p{L}\n]*\s*(?:Autista|Driver)\s*:\s*(.+)$/iu],
    ['Fornitori', /^[^\p{L}\n]*\s*(?:Fornitori?|Supplier s?|Suppliers?)\s*:\s*(.+)$/iu],
    ['Modalità', /^[^\p{L}\n]*\s*(?:Modalit[àa]|Mode|Payment)\s*:\s*(.+)$/iu],
    ['Tariffa', /^[^\p{L}\n]*\s*(?:Tariffa|Fare)\s*:\s*(.+)$/iu],
    ['Note', /^[^\p{L}\n]*\s*(?:Note|Notes)\s*:\s*(.+)$/iu],
    ['Id', /^[^\p{L}\n]*\s*(?:Id|Rif)\s*:\s*(.+)$/iu]
  ];
  const pulisci = (v) => String(v)
    .replace(/<\/?[a-z][^>]*>/gi, '')            // via i tag HTML (<code>, <a href…>)
    .replace(/\s*🗺️\s*Maps\s*$/i, '')
    .replace(/\s*\(\s*(?:luned|marted|mercoled|gioved|venerd|sabato|domenica)[^)]*\)\s*$/i, '')
    .replace(/[*_~`]/g, '').trim();
  const blocchi = String(testo || '').split(/\|\|\||\n[^\p{L}\n]*[━─—═]{4,}[^\p{L}\n]*\n/u);
  // riga in stile recap dal foglio: «🗓 Sabato 08/08/2026 at 10:35» oppure «📅 dom 9 agosto 2026 ore 02:00»
  const RIGA_DATA_ORA = /^[^\p{L}\d\n]*\s*(?:[a-zà-ÿ]+\.?\s+)?(\d{1,2}[\/.]\d{1,2}[\/.]\d{2,4}|\d{1,2}\s+[a-zà-ÿ]+\s+\d{4})\s*(?:at|alle|ore|·)?\s*(\d{1,2}:\d{2})?\s*$/iu;
  const righe = [];
  for (const b of blocchi) {
    const r = {};
    for (const l of b.split('\n')) {
      if (r['Data'] === undefined) {
        const md = l.match(RIGA_DATA_ORA);
        if (md && !/:\s*\S/.test(l.replace(/\d{1,2}:\d{2}/, ''))) {
          r['Data'] = pulisci(md[1]);
          if (md[2] && r['Time'] === undefined) r['Time'] = md[2];
          continue;
        }
      }
      for (const [chiave, re] of ETI) {
        if (r[chiave] !== undefined) continue;
        const m = l.match(re);
        if (m) { const v = pulisci(m[1]); if (v) r[chiave] = v; break; }
      }
    }
    // una scheda vera ha almeno data/ora + una tratta
    if ((r['Data'] || r['Time']) && (r['Da'] || r['Per'])) righe.push(r);
  }
  return righe;
}

// ============================================================================
// RIDISEGNA LA SCHEDA — il modello scrive i campi come gli viene, il codice li
// rimette in ordine con le emoji giuste. La prosa attorno resta intatta, e i
// campi che il codice non conosce NON si perdono: li ricopia in coda.
// ============================================================================
function ridisegnaSchede(testo) {
  const ORDINE = [
    ['Allert', '🔔', 'Allert'], ['Data', '📅', 'Data'], ['Time', '🕐', 'Ora'],
    ['Da', '📍', 'Da'], ['Per', '🎯', 'Per'], ['Pax', '👥', 'Pax'], ['Nome', '🧑', 'Nome'],
    ['Cell.', '📞', 'Cell.'], ['Volo', '✈️', 'Volo'], ['Fornitori', '🏢', 'Fornitori'],
    ['Modalità', '💳', 'Modalità'], ['Autista', '🚖', 'Autista'], ['Veicolo', '🚗', 'Veicolo'],
    ['h extra', '⏱️', 'h extra'], ['Tariffa', '💰', 'Tariffa'], ['Acconto', '💶', 'Acconto'],
    ['%', '📊', '%'], ['Fee', '💼', 'Fee'], ['Sub-appalti', '🧾', 'Sub-appalti'],
    ['Note', '📝', 'Note'], ['Id', '🆔', 'Id']
  ];
  const ETI = [
    ['Allert', /^[^\p{L}\n]*\s*Allert\s*:\s*(.*)$/iu],
    ['Data', /^[^\p{L}\n]*\s*(?:Data|Date)\s*:\s*(.*)$/iu],
    ['Time', /^[^\p{L}\n]*\s*(?:Ora|Time)\s*:\s*(.*)$/iu],
    ['Da', /^[^\p{L}\n]*\s*(?:Da|From)\s*:\s*(.*)$/iu],
    ['Per', /^[^\p{L}\n]*\s*(?:Per|To)\s*:\s*(.*)$/iu],
    ['Pax', /^[^\p{L}\n]*\s*Pax\s*:\s*(.*)$/iu],
    ['Nome', /^[^\p{L}\n]*\s*(?:Nome|Name)\s*:\s*(.*)$/iu],
    ['Cell.', /^[^\p{L}\n]*\s*(?:Cell\.?|Phone|Telefono)\s*:\s*(.*)$/iu],
    ['Volo', /^[^\p{L}\n]*\s*(?:Volo|Flight)\s*:\s*(.*)$/iu],
    ['Fornitori', /^[^\p{L}\n]*\s*(?:Fornitori?|Suppliers?)\s*:\s*(.*)$/iu],
    ['Modalità', /^[^\p{L}\n]*\s*(?:Modalit[àa]|Mode|Payment)\s*:\s*(.*)$/iu],
    ['Autista', /^[^\p{L}\n]*\s*(?:Autista|Driver)\s*:\s*(.*)$/iu],
    ['Veicolo', /^[^\p{L}\n]*\s*(?:Veicolo|Vehicle)\s*:\s*(.*)$/iu],
    ['h extra', /^[^\p{L}\n]*\s*h\s*extra\s*:\s*(.*)$/iu],
    ['Tariffa', /^[^\p{L}\n]*\s*(?:Tariffa|Fare)\s*:\s*(.*)$/iu],
    ['Acconto', /^[^\p{L}\n]*\s*(?:Acconto|Deposit)\s*:\s*(.*)$/iu],
    ['%', /^[^\p{L}\n]*\s*%\s*:\s*(.*)$/iu],
    ['Fee', /^[^\p{L}\n]*\s*Fee\s*:\s*(.*)$/iu],
    ['Sub-appalti', /^[^\p{L}\n]*\s*Sub-?appalti\s*:\s*(.*)$/iu],
    ['Note', /^[^\p{L}\n]*\s*(?:Note|Notes)\s*:\s*(.*)$/iu],
    ['Id', /^[^\p{L}\n]*\s*(?:Id|Rif)\s*:\s*(.*)$/iu]
  ];
  const righe = String(testo || '').split('\n');
  const fuori = [];
  let i = 0;
  while (i < righe.length) {
    // inizio di un gruppo di campi
    let j = i, campi = 0;
    const trovati = {}, ignoti = [];
    while (j < righe.length) {
      const l = righe[j];
      if (!l.trim()) {                     // una riga vuota dentro il gruppo lo chiude
        break;
      }
      let quale = null;
      for (const [k, re] of ETI) { const m = l.match(re); if (m) { quale = [k, m[1]]; break; } }
      if (quale) {
        campi++;
        if (trovati[quale[0]] === undefined) trovati[quale[0]] = quale[1].trim();
        else ignoti.push(l);               // campo ripetuto: non lo perdo
        j++;
        continue;
      }
      if (/^[^\p{L}\n]*\s*[\p{L}][\p{L} .%'-]{1,18}\s*:\s*\S/u.test(l) && campi > 0) {
        ignoti.push(l); j++; continue;     // «Qualcosa: valore» che non conosco
      }
      break;
    }
    // se la scheda è stata scritta in inglese (Agostino ha chiesto la traduzione),
    // NON la si ritocca: il ridisegno parla italiano e la rovinerebbe.
    const INGLESE = /^[^\p{L}\n]*\s*(Date|From|To|Name|Flight|Supplier|Payment|Driver|Vehicle|Fare|Booking\s+code)\s*:/iu;
    const inInglese = righe.slice(i, j).some((l) => INGLESE.test(l));
    if (campi >= 3 && trovati['Id'] !== undefined && !inInglese) {
      const out = [];
      for (const [k, em, lab] of ORDINE) {
        const v = trovati[k];
        if (v === undefined || v === '') continue;
        out.push(em + ' ' + lab + ': ' + v);
      }
      for (const l of ignoti) out.push(l.trim());
      fuori.push(out.join('\n'));
      i = j;
    } else {
      fuori.push(righe[i]); i++;
    }
  }
  return fuori.join('\n');
}

// ============================================================================
// HTML SICURO PER TELEGRAM — 07/08/2026
// Telegram RIFIUTA l'intero messaggio se trova un tag non bilanciato («can't parse
// entities: Unexpected end tag») e il bot resta MUTO. Successo il 07/08 alle 11:09:
// il modello aveva scritto «📍 Da: X → 🎯 Per: Y» su UNA riga, il link Maps veniva
// aggiunto due volte e usciva «...">Maps</a>">Maps</a>».
// Qui si tengono solo i tag ammessi, si buttano le chiusure orfane e si chiude ciò
// che è rimasto aperto: meglio un messaggio senza un grassetto che nessun messaggio.
// ============================================================================
function htmlSicuro(testo) {
  const AMMESSI = ['b', 'strong', 'i', 'em', 'u', 'ins', 's', 'strike', 'del', 'code', 'pre', 'a', 'tg-spoiler', 'blockquote'];
  const pila = [];
  let out = '';
  const rx = /<\/?([a-zA-Z][a-zA-Z0-9-]*)((?:\s[^<>]*)?)\/?>/g;
  let ultimo = 0, m;
  while ((m = rx.exec(String(testo || '')))) {
    out += String(testo).slice(ultimo, m.index);
    ultimo = m.index + m[0].length;
    const tag = m[1].toLowerCase();
    const chiusura = m[0][1] === '/';
    if (!AMMESSI.includes(tag)) continue;              // tag non ammesso: via
    if (chiusura) {
      const dove = pila.lastIndexOf(tag);
      if (dove === -1) continue;                       // chiusura orfana: via
      // chiudi anche gli eventuali tag aperti dopo, per non incrociarli
      while (pila.length > dove) out += '</' + pila.pop() + '>';
    } else {
      pila.push(tag);
      out += '<' + tag + (m[2] || '') + '>';
      continue;
    }
  }
  out += String(testo).slice(ultimo);
  while (pila.length) out += '</' + pila.pop() + '>';  // chiudi i rimasti aperti
  return out;
}

// Aggiunge i link Maps a Da/Per in UN SOLO passaggio: così il secondo campo non
// può ritrovarsi il link del primo dentro il valore (era la causa del tag doppio).
function aggiungiMaps(testo) {
  // idempotente: se i link Maps ci sono già, si togliono e si rifanno una volta sola
  testo = String(testo || '')
    .replace(/[ \t]*🗺️[ \t]*<a\s[^>]*>[^<]*<\/a>/g, '')
    .replace(/[ \t]*🗺️[ \t]*Maps\b/g, '');
  // il valore si ferma prima di: un link Maps già presente, un tag, l'altro campo,
  // una freccia (il modello a volte scrive «Da: X → Per: Y» su una riga), o il fine riga
  const RX = /(📍\s*(?:Da|From)\s*:|🎯\s*(?:Per|To)\s*:)[ \t]*([^\n]*?)(?=[ \t]*(?:🗺️|<a\s|📍|🎯|→|->|\n|$))/g;
  return String(testo || '').replace(RX, (tutto, etichetta, valore) => {
    const v = String(valore).replace(/<[^>]*>/g, '').trim();
    if (!v) return tutto;
    const h = v.match(/https?:\/\/\S+/);
    const url = h ? h[0] : 'https://www.google.com/maps?q=' + encodeURIComponent(v);
    return etichetta + ' ' + v + '  🗺️ <a href="' + url.replace(/"/g, '%22') + '">Maps</a>';
  });
}

// ============================================================================
// VIA IL RAGIONAMENTO — 07/08/2026 (Agostino: «taglia»)
// Il modello a volte manda in chat i suoi pensieri: «Agostino sta insistendo…»,
// «Devo capire cosa intende…», «Ho i luoghi normalizzati…». Non servono a nessuno.
// Si toglie SOLO un capoverso che parla del ragionamento e che non contiene:
// una domanda, un campo di scheda, un link, un avviso ⚠️/✅, un Id.
// Se dopo il taglio non resta niente, si tiene il testo originale: meglio un
// pensiero di troppo che un messaggio vuoto.
// ============================================================================
function tagliaRagionamento(testo) {
  const t = String(testo || '');
  if (!t.trim()) return t;
  const META = /\bAgostino\b|\bdevo\b|\bdovrei\b|\bdobbiamo\b|\bprocedo\b|\bprocediamo\b|\bmostro\b|\binterpreto\b|\bvaluto\b|\bassumo\b|\bevidentemente\b|\bprobabilmente\b|\bcandidat[oi]\b|\bintent\b|\bfuzzy\b|normalizzat|\btool\b|\bturno\b|\bfoglio\b.*\bcolonn/i;
  const CAMPO_R = /^[^\p{L}\n]*\s*(Data|Date|Ora|Time|Da|From|Per|To|Pax|Nome|Name|Fornitor\w*|Modalit[àa]|Tariffa|Fare|Cell\.?|Volo|Flight|Autista|Veicolo|Note|Acconto|Id)\s*:/imu;
  const capoversi = t.split(/\n\s*\n/);
  const tenuti = capoversi.filter((c) => {
    const s = c.trim();
    if (!s) return false;
    if (!META.test(s)) return true;                 // non è ragionamento
    if (s.includes('?')) return true;               // è una domanda per Agostino
    if (/^se\s+vuoi\s+puoi\s+aggiungere/i.test(s)) return true;   // riga utile, non un pensiero
    if (/^\s*(?:\d+[.)]|[-•*])\s+\S/m.test(s)) return true;       // elenco: dentro c'è la sostanza
    if (CAMPO_R.test(s)) return true;               // è una scheda
    if (/TR[\/-]\d{8}[\/-][A-Za-z0-9-]{4,}/.test(s)) return true;
    if (/https?:\/\/|wa\.me|<a\s/i.test(s)) return true;
    if (/^[^\p{L}\n]*(⚠️|✅|❌|🗑️|⏳|💬|🏢|🚗|🔄|📋)/u.test(s)) return true;
    if (/\|\|\||━{3,}/.test(s)) return true;
    return false;                                   // ragionamento: via
  });
  const fuori = tenuti.join('\n\n').trim();
  return fuori ? fuori : t;
}

