// Estrae testo da .docx (Word) — parser ZIP minimale
// .docx è un ZIP che contiene word/document.xml; il testo è nei tag <w:t>
const item = $input.first();
const bin = item.binary;
if (!bin) return [{ json: { text: '⚠️ File Word non trovato', kind: 'document' } }];
const bkey = Object.keys(bin)[0];
const b64 = bin[bkey].data;
if (!b64) return [{ json: { text: '⚠️ Binary Word vuoto', kind: 'document' } }];

let text = '';
try {
  const JSZip = require('jszip');
  const zip = await JSZip.loadAsync(b64, { base64: true });
  const docFile = zip.file('word/document.xml');
  if (!docFile) {
    return [{ json: { text: '⚠️ document.xml mancante nel .docx', kind: 'document' } }];
  }
  const xml = await docFile.async('string');
  // Estrai tutti i <w:t>...</w:t> mantenendo paragrafi (<w:p>) come a-capo
  const paras = xml.split(/<w:p[\s>]/);
  const out = [];
  for (const p of paras) {
    const tags = p.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
    const line = tags.map(t => t.replace(/<[^>]+>/g, '')).join('');
    if (line.trim()) out.push(line);
  }
  text = out.join('\n').trim();
} catch (e) {
  return [{ json: { text: '⚠️ Errore parsing .docx: ' + String(e).slice(0,200), kind: 'document', error: String(e) } }];
}

if (!text) text = '⚠️ Documento Word vuoto o non leggibile';

return [{
  json: {
    text: '📝 Documento Word ricevuto.\n\n' + text.slice(0, 50000),
    kind: 'document',
    charCount: text.length
  }
}];

