const item = $input.item.json;
const tg = item.telegram || {};
// GUARDIA ANTI-MURO (11/07/2026): se il modello si incanta e ripete i caratteri-linea
// (es. 16.000 volte ━), comprimi ogni sequenza di 40+ a un separatore standard di 24.
const fullRaw = String(tg.text || '');
const full = fullRaw.replace(/[━─═▬]{40,}/g, '━'.repeat(24));
const pm = tg.parse_mode || 'HTML';
const rmk = item.replyMarkupJson || null;
// === QUANTO È LUNGO UN MESSAGGIO PER TELEGRAM (07/08/2026) ===
// Provato sul campo con il bot: Telegram conta i caratteri CHE SI VEDONO, non gli indirizzi
// dentro i link. Un messaggio da 9.317 caratteri grezzi con 3 link passa; uno da 12.258 con
// 4 link viene rifiutato con ENTITIES_TOO_LONG. Quindi i limiti veri sono due:
//   • 4096 caratteri visibili
//   • circa 10 KB di indirizzi nei link (10240 byte, ~50 di contorno per ogni link)
// Prima si misurava il testo GREZZO: un recap con 5 link precompilati (che dentro l'URL si
// portano tutto il messaggio per cliente, fornitore e autista) sfondava i 3800 subito e
// Agostino si ritrovava 5-6 messaggi di seguito per un solo salvataggio.
const VIS = (s) => String(s === undefined || s === null ? '' : s)
  .replace(/<a\s+href="[^"]*">/gi, '').replace(/<\/?[a-z][^>]*>/gi, '');
const PESO_LINK = (s) => {
  let n = 0, m; const re = /<a\s+href="([^"]*)"/gi;
  while ((m = re.exec(String(s === undefined || s === null ? '' : s)))) n += m[1].length + 64;
  return n;
};
const TETTO_VIS = 3800, TETTO_LINK = 9500;
const STA = (s, maxVis) => VIS(s).length <= (maxVis || TETTO_VIS) && PESO_LINK(s) <= TETTO_LINK;

const LIMIT = 3800;

const safeCut = (s) => {
  let t = s.trim();
  // si taglia sui caratteri VISIBILI: tagliare il testo grezzo spezzava i link
  while (VIS(t).length > 4096 && t.length > 100) t = t.slice(0, Math.floor(t.length * 0.9));
  const lastOpen = t.lastIndexOf('<');
  if (lastOpen > -1 && t.indexOf('>', lastOpen) === -1) t = t.slice(0, lastOpen);
  let opens = (t.match(/<a\b/gi) || []).length;
  let closes = (t.match(/<\/a>/gi) || []).length;
  while (opens > closes) {
    const lastA = t.lastIndexOf('<a');
    if (lastA === -1) break;
    t = t.slice(0, lastA);
    opens = (t.match(/<a\b/gi) || []).length;
    closes = (t.match(/<\/a>/gi) || []).length;
  }
  return t.trim();
};

let blocks = full.includes('|||')
  ? full.split('|||').map(s => s.trim()).filter(s => s.length)
  : [full];

const messages = [];
for (const block of blocks) {
  if (STA(block, LIMIT)) { messages.push(block); continue; }
  let pieces = block.split(/(?=\n━━━)/);
  const atomic = [];
  for (const p of pieces) { for (const s of p.split(/(?=\n<a\s)/)) atomic.push(s); }
  pieces = atomic;
  const chunks = [];
  for (const piece of pieces) {
    const last = chunks.length - 1;
    if (chunks.length && STA(chunks[last] + piece, LIMIT)) { chunks[chunks.length - 1] += piece; }
    else { chunks.push(piece); }
  }
  for (const c of chunks) { messages.push(c); }
}

// GUARDIA ANTI-MURO parte 2: scarta i messaggi senza contenuto vero (solo linee/simboli).
// Fallback: se cosi' resterebbe vuoto, tieni il testo originale ripulito (per non perdere i bottoni).
let out = messages.map(safeCut).filter(t => t.length && /[\p{L}\p{N}]/u.test(t));
if (!out.length) out = [safeCut(full)].filter(t => t.length);
return out.map((t, i) => ({
  json: {
    telegram: { text: t, parse_mode: pm },
    replyMarkupJson: (i === out.length - 1) ? rmk : null
  }
}));

