      if (arrivo) p.push('• Airport transfers: please notify any flight delay in advance — no-show without notice forfeits the 50% deposit.');
      p.push('• Cancellations over 48h before: full refund. 24–48h: 50% deposit retained. Within 24h or no-show: 100% retained.');
