    if (r.per) o.push('🎯 ' + L.per + ': ' + r.per);
    if (r.pax) o.push('👥 ' + r.pax + ' ' + L.pax);
    if (r.volo) o.push('✈️ ' + L.volo + ': ' + r.volo);
    const t = soldi(r.tariffa);
    if (t) {
      const nota = DA_INCASSARE.test(r.modalita) ? (en ? ' (to be paid to the driver)' : ' (da saldare all\'autista)')
