function makeHelpers() {
  const WDNAME = ['domenica','lunedì','martedì','mercoledì','giovedì','venerdì','sabato'];
  const WD = { domenica:0, lunedi:1, martedi:2, mercoledi:3, giovedi:4, venerdi:5, sabato:6,
               sunday:0, monday:1, tuesday:2, wednesday:3, thursday:4, friday:5, saturday:6 };
  const MESI = { gennaio:1,febbraio:2,marzo:3,aprile:4,maggio:5,giugno:6,luglio:7,agosto:8,settembre:9,ottobre:10,novembre:11,dicembre:12,
                 january:1,february:2,march:3,april:4,may:5,june:6,july:7,august:8,september:9,october:10,november:11,december:12 };
  const pad = n => String(n).padStart(2,'0');
  const strip = s => String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
  const wdOf = (y,mo,d) => new Date(Date.UTC(y, mo-1, d, 12)).getUTCDay();
  const addDays = (y,mo,d,delta) => { const t=new Date(Date.UTC(y,mo-1,d,12)); t.setUTCDate(t.getUTCDate()+delta); return [t.getUTCFullYear(), t.getUTCMonth()+1, t.getUTCDate()]; };
  const dmy = (y,mo,d) => pad(d)+'/'+pad(mo)+'/'+y;
  const snapToWeekday = (y,mo,d, targetWd) => { const cur = wdOf(y,mo,d); let diff = targetWd - cur; if (diff>3) diff-=7; if (diff<-3) diff+=7; return addDays(y,mo,d,diff); };
  return { WDNAME, WD, MESI, pad, strip, wdOf, addDays, dmy, snapToWeekday };
}
function parseCustomerSignals(custText, now) {
  const H = makeHelpers();
  const t = H.strip(custText);
  const weekdays = new Set();
  for (const k in H.WD) { if (new RegExp('\\b'+k+'\\b').test(t)) weekdays.add(H.WD[k]); }
  const dayNums = new Set(); let m;
  const reWdNum = new RegExp('(?:'+Object.keys(H.WD).join('|')+')\\s+(\\d{1,2})\\b','g');
  while ((m = reWdNum.exec(t))) dayNums.add(parseInt(m[1],10));
  const reNumMese = new RegExp('\\b(\\d{1,2})\\s+(?:'+Object.keys(H.MESI).join('|')+')','g');
  while ((m = reNumMese.exec(t))) dayNums.add(parseInt(m[1],10));
  const explicit = [];
  const reD = /\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/g;
  while ((m = reD.exec(t))) { const dd=parseInt(m[1],10), mm=parseInt(m[2],10); if (dd>=1&&dd<=31&&mm>=1&&mm<=12){ let yy=m[3]?parseInt(m[3],10):null; if(yy&&yy<100) yy+=2000; explicit.push({dd,mm,yy}); } }
  let relative = null;
  if (now && /\bdopodomani\b/.test(t)) relative = H.addDays(now.y,now.mo,now.d,2);
  else if (now && /\bdomani\b/.test(t)) relative = H.addDays(now.y,now.mo,now.d,1);
  else if (now && /\boggi\b/.test(t)) relative = [now.y,now.mo,now.d];
  return { weekdays, dayNums, explicit, relative };
}
function resolveOne(dd, mm, yy, parenName, sig, bozzaDate, isSingle) {
  const H = makeHelpers();
  let y=yy, mo=mm, d=dd;
  const wd = H.wdOf(y,mo,d);
  const custWd = isSingle ? sig.weekdays : new Set();
  let exp = null;
  if (isSingle) { if (sig.relative) exp={dd:sig.relative[2],mm:sig.relative[1],yy:sig.relative[0]}; else if (sig.explicit.length===1) exp={dd:sig.explicit[0].dd,mm:sig.explicit[0].mm,yy:sig.explicit[0].yy||y}; }
  if (exp && custWd.size>=1) { const ewd=H.wdOf(exp.yy||y,exp.mm,exp.dd); if (!custWd.has(ewd)) return { block:true }; }
  if (exp) { const ey=exp.yy||y; if (!(exp.dd===d && exp.mm===mo && ey===y)) return { y:ey, mo:exp.mm, d:exp.dd, changed:true, reason:'data esplicita cliente' }; }
  // v4.1 (27/07): l'etichetta-giorno tra parentesi del recap NON sposta MAI il numero.
  // Spesso e' un'etichetta sbagliata dell'AI (es. 12/08 etichettato 'domenica'): il NUMERO resta,
  // l'etichetta viene ri-timbrata da verificaRecap. Il numero si sposta SOLO su giorno-settimana
  // ESPLICITO del cliente nel turno (priorita' 2, sotto).
  if (custWd.size>=1) {
    if (sig.dayNums.has(d) && !custWd.has(wd)) return { block:true };
    if (!custWd.has(wd)) { let best=null,bestDiff=1e18,bestWd=null; for (const twd of custWd){ const s=H.snapToWeekday(y,mo,d,twd); const diff=Math.abs(new Date(Date.UTC(s[0],s[1]-1,s[2]))-new Date(Date.UTC(y,mo-1,d))); if(diff<bestDiff){bestDiff=diff;best=s;bestWd=twd;} } if(best) return { y:best[0],mo:best[1],d:best[2],changed:true,reason:'giorno-settimana cliente ('+H.WDNAME[bestWd]+')' }; }
  }
  if (parenName==null && custWd.size===0 && bozzaDate) { const bm=/(\d{1,2})\/(\d{1,2})\/(\d{4})/.exec(bozzaDate); if (bm){ const bd=+bm[1],bmo=+bm[2],byy=+bm[3]; if(!(bd===d&&bmo===mo&&byy===y)) return { y:byy,mo:bmo,d:bd,changed:true,reason:'data decisa in precedenza (Id)' }; } }
  return { y,mo,d, changed:false, reason:'' };
}
function verificaRecap(recap, sig, bozzeById) {
  const H = makeHelpers();
  const dataLineRx = /📅[ \t]*Data:[ \t]*(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[ \t]*\(\s*([^)]*?)\s*\))?/g;
  let count=0, tmp; const rc=new RegExp(dataLineRx.source,'g'); while((tmp=rc.exec(recap))) count++;
  const isSingle = count<=1;
  // FIX 30/07/2026 — la memoria bozza va letta dall'Id DEL BLOCCO a cui appartiene la riga data.
  // Prima si prendeva il PRIMO Id del recap e lo si applicava a TUTTE le righe: in un recap
  // multi-transfer ogni data veniva forzata a quella del primo transfer (caso Jonny De Napoli
  // 29/07: 31/07 + 01/08 + 02/08 + 02/08 salvati tutti come 31/07).
  const bozzaDateAt = (off) => {
    if (!bozzeById) return null;
    const after = recap.slice(off);
    const nxt = after.indexOf('\u{1F4C5}', 1);
    const scope = (nxt === -1) ? after : after.slice(0, nxt);
    const im = /TR\/\d{8}\/[A-Z0-9]{4,20}/.exec(scope);
    return (im && bozzeById[im[0]]) ? bozzeById[im[0]] : null;
  };
  let blocked=false; const notes=[];
  const out = recap.replace(dataLineRx, (full, dd, mm, yy, paren, off) => {
    const r = resolveOne(parseInt(dd,10), parseInt(mm,10), parseInt(yy,10), (paren!==undefined?paren:null), sig, bozzaDateAt(off), isSingle);
    if (r.block) { blocked=true; return full; }
    const y=r.y, mo=r.mo, d=r.d; const gname=H.WDNAME[H.wdOf(y,mo,d)];
    if (r.changed) notes.push(H.dmy(+dd,+mm,+yy)+' → '+H.dmy(y,mo,d)+' ('+gname+') — '+r.reason);
    return '📅 Data: '+H.dmy(y,mo,d)+' ('+gname+')';
  });
  return { text: out, changed: notes.length>0, blocked, notes };
}

function dedupById(text){
  text=String(text||'');
  const idRe=/🆔[^\n]*?(TR\/\d{8}\/[A-Z0-9]{4,20})/g;
  const pos=[]; let m;
  while((m=idRe.exec(text))){ let eol=text.indexOf('\n', m.index); if(eol===-1) eol=text.length; pos.push({id:m[1], end:eol}); }
  if(pos.length<2) return {text, dropped:false};
  const seen=new Set(); let cursor=0, dropped=false; const kept=[];
  for(const p of pos){ const block=text.slice(cursor,p.end); if(seen.has(p.id)){dropped=true;} else {seen.add(p.id); kept.push(block);} cursor=p.end; }
  let res=kept.join('')+text.slice(cursor);
  res=res.replace(/\n{3,}/g,'\n\n');
  return {text:res, dropped};
}

