  const strip = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const chiave = (s) => strip(s).replace(/[^a-z]/g, '');
  const wdDaParola = (s) => { const x = chiave(s); return WD[x] !== undefined ? WD[x] : null; };
  const meseDaParola = (s) => { const x = chiave(s); return MESI[x] !== undefined ? MESI[x] : null; };
  const pad = (n) => String(n).padStart(2, '0');
  const wdOf = (y, mo, d) => new Date(Date.UTC(y, mo - 1, d, 12)).getUTCDay();
