  const dataValida = (y, mo, d) => {
    if (!(y >= 1970 && y <= 2100 && mo >= 1 && mo <= 12 && d >= 1 && d <= 31)) return false;
    const t = new Date(Date.UTC(y, mo - 1, d, 12));
    return t.getUTCFullYear() === y && t.getUTCMonth() + 1 === mo && t.getUTCDate() === d;
  };
