// per scegliere il rientro #4 non viene mai confuso con quattro euro.
function leggiImporto(testo) {
  let t = String(testo == null ? '' : testo).trim().toLowerCase();
  t = t.replace(/^(?:euro|eur|€)\s*/, '').replace(/\s*(?:euro|eur|€)\s*$/, '').trim();
  if (!/^[0-9]{1,6}(?:[.,][0-9]{1,2})?$/.test(t)) return null;
  let intero = t, dec = '';
  const m = t.match(/^([0-9]{1,6})[.,]([0-9]{1,2})$/);
  if (m) { intero = m[1]; dec = m[2]; }
  const numero = parseFloat(intero + (dec ? '.' + dec : ''));
  if (isNaN(numero) || numero < 0 || numero > 100000) return null;
  if (/^0+$/.test(dec)) dec = '';
  const perFoglio = intero.replace(/^0+(?=\d)/, '') + (dec ? ',' + dec : '');
  return { numero: numero, perFoglio: perFoglio };
}
// L'attesa vale mezz'ora: oltre, meglio che il numero torni a essere un numero qualunque.
function attesaValida(dati, adesso, minuti) {
