const testa = (v[0] || []).map((c) => String(c).trim());
const iId = testa.indexOf('Id');
const presenti = new Set();
for (let i = 1; i < v.length; i++) {
  const s = String((v[i] || [])[iId] || '').trim();
  if (s) presenti.add(s);
}
const voluti = $('Vale come importo?').all().map((i) => i.json).filter((j) => j && j.ok);
const dentro = voluti.filter((j) => presenti.has(String(j.Id)));
const fuori = voluti.filter((j) => !presenti.has(String(j.Id)));
if (!dentro.length) {
  return [{ json: { scrivo: false, quanti_fuori: fuori.length,
                    id: (fuori[0] || {}).Id || '', tariffa: (fuori[0] || {}).Tariffa || '' } }];
}
return dentro.map((j) => ({ json: Object.assign({}, j, { scrivo: true, quanti_fuori: fuori.length }) }));

// ============================================================================
// BOZZE — CHIEDI COSA SALVARE  ·  14/08/2026
// Nasce dal 14/08 sera: l'agente ha salvato 1 transfer su 3 e ha scritto gli altri
// due in una riga di prosa («⏳ In sospeso: …»). Quella riga si legge e si dimentica.
// Da qui in poi, se dopo un salvataggio restano bozze aperte, arriva un messaggio a
// parte con i BOTTONI: quale salvare, tutte, o scartare. Niente prosa da interpretare.
// Il messaggio è volutamente COMPATTO (una riga per bozza, nessuna riga «Campo:»):
// così non viene scambiato per una scheda né da Aggiorna Bozze né da Componi Payload
// Salvataggio. Le schede vere le rimette l'agente quando premi un bottone.
// ============================================================================
const src = $('Aggiorna Bozze').first().json;
const bozze = Array.isArray(src.bozze) ? src.bozze : [];

// si parla solo dopo un turno di salvataggio, e solo se è rimasto qualcosa fuori
if (!src.salvando || bozze.length === 0) return [];

function campo(scheda, nomi) {
  const re = new RegExp('^[^\\p{L}\\n]*\\s*(?:' + nomi + ')\\s*:\\s*(.+)$', 'iu');
  for (const riga of String(scheda || '').split('\n')) {
    const m = riga.match(re);
    if (m && m[1].trim()) return m[1].trim();
  }
  return '';
}
function taglia(s, n) { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; }

const NUM = ['1️⃣','2️⃣','3️⃣','4️⃣','5️⃣','6️⃣','7️⃣','8️⃣','9️⃣','🔟'];
const MAX = 10;                       // oltre 10 bottoni la tastiera diventa illeggibile
const mostrate = bozze.slice(0, MAX);

const righe = [];
const tastiera = [];
mostrate.forEach((b, i) => {
  const data = campo(b.scheda, 'Data|Date').replace(/\s*\([^)]*\)\s*/g, ' ').trim();
  const ora  = campo(b.scheda, 'Ora|Time');
  const per  = campo(b.scheda, 'Per|To|Transfer\\s*<\\s*Per');
  const nome = campo(b.scheda, 'Nome|Name');
  const tar  = campo(b.scheda, 'Tariffa|Fare');
  const pezzi = [data, ora, per, nome, tar ? tar.replace(/\s*€?$/, '') + '€' : ''].filter(Boolean);
  righe.push(`${NUM[i]} ${pezzi.join(' · ')}`);
  // etichetta del bottone: ora + destinazione, quel che basta a riconoscerla
  const etichetta = taglia([ora, per || nome].filter(Boolean).join(' ') || 'questa', 26);
  // callback_data: massimo 64 byte (limite Telegram)
  const cb = ('salva ' + b.id).slice(0, 64);
  tastiera.push([{ text: `${NUM[i]} Salva ${etichetta}`, callback_data: cb }]);
});

if (bozze.length > mostrate.length) {
  righe.push(`… e altre ${bozze.length - mostrate.length}`);
}
if (bozze.length > 1) {
  tastiera.push([{ text: `💾 Salva tutte e ${bozze.length}`, callback_data: 'salva tutte le bozze in sospeso' }]);
}
tastiera.push([{ text: '🗑️ Scarta tutte', callback_data: 'annulla tutte le bozze' }]);

const testo = [
  bozze.length === 1
    ? '⏳ <b>Resta 1 bozza aperta</b> — sul gestionale non c\'è.'
    : `⏳ <b>Restano ${bozze.length} bozze aperte</b> — sul gestionale non ci sono.`,
  '',
  righe.join('\n'),
  '',
  'Che faccio?'
].join('\n');

return [{ json: {
  chat_id: src.chat_id,
  telegram: { text: testo, parse_mode: 'HTML' },
  replyMarkupJson: JSON.stringify({ inline_keyboard: tastiera }),
  n_bozze: bozze.length
} }];

// ============================================================================
// BUFFER MESSAGGI v2 — SONO L'ULTIMO?  ·  15/08/2026
// v1 (14/08) metteva in coda solo il testo. Il 15/08 alle 09:19 sono arrivati
// una foto e un testo a 235 millesimi di distanza («…ora ti mando i dettagli
// del volo») e sono rimasti DUE turni separati: l'agente ha risposto al testo
// senza la foto, e poi ha visto la foto senza il discorso.
// v2 mette in coda anche foto, vocali e documenti. Le regole, in chiaro:
//
//   • UN ALLEGATO VA SEMPRE AVANTI. Non si ferma mai, non si butta mai: il suo
//     contenuto lo sa leggere solo il ramo che lo scarica.
//   • IL PRIMO ALLEGATO DEL GRUPPO SI PRENDE IL TESTO. I messaggi di testo
//     arrivati insieme diventano la sua didascalia, così l'agente vede la foto
//     e la frase nello stesso turno.
//   • UN TESTO SI FERMA solo se in coda c'è un allegato che se lo prenderà.
//     Se l'allegato è già passato (riga sparita), il testo va avanti da solo:
//     meglio una risposta in più che una frase del cliente lasciata cadere.
//   • FRA SOLI TESTI vale la regola di prima: parla l'ultimo, con tutto unito.
//   • I click sui bottoni non passano di qui: devono restare immediati.
// ============================================================================
const mio = $('Telegram Trigger1').first().json;
const mioUpdate = Number(mio.update_id || 0);
const mioMsg = mio.message || {};
const sonoTesto = !!(mioMsg.text && String(mioMsg.text).trim());

const righe = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.updateid != null);

const testi = righe.filter((r) => r.genere === 'testo');
const media = righe.filter((r) => r.genere === 'media');

// ---------- caso 1: io sono un ALLEGATO ----------
if (!sonoTesto) {
  // solo il PRIMO allegato del gruppo si prende il testo: gli altri restano
  // allegati semplici, altrimenti la stessa frase finirebbe su ogni foto.
  const primoMedia = media.reduce(
    (m, r) => (m === null || Number(r.updateid) < Number(m) ? Number(r.updateid) : m), null);
  const sonoIlPrimo = (primoMedia === null || primoMedia === mioUpdate);

  const presi = sonoIlPrimo ? testi.slice().sort((a, b) => a.updateid - b.updateid) : [];
  const didascalia = [String(mioMsg.caption || '').trim()]
    .concat(presi.map((r) => String(r.testo || '').trim()))
    .filter(Boolean).join('\n');

  const messaggio = Object.assign({}, mioMsg);
  if (didascalia) messaggio.caption = didascalia;

  // si ripuliscono la mia riga e i testi che mi sono preso. MAI le righe degli
  // altri allegati: devono trovarle loro quando si svegliano.
  const daCancellare = presi.map((r) => r.id).concat(righe.filter((r) => Number(r.updateid) === mioUpdate).map((r) => r.id));

  return [{ json: {
    update_id: mioUpdate,
    message: messaggio,
    _buffer_uniti: presi.length + 1,
    _buffer_allegato: true,
    _da_cancellare: daCancellare.filter((x) => x != null)
  } }];
}

// ---------- caso 2: io sono TESTO ----------
// c'è un allegato in coda? allora se lo prende lui, io mi fermo in silenzio
if (media.length) return [];

// c'è un testo più recente del mio? parla lui
const piuRecente = testi.reduce((m, r) => Math.max(m, Number(r.updateid || 0)), 0);
if (piuRecente > mioUpdate) return [];

// sono l'ultimo: unisco i testi in ordine di arrivo
const ordinati = testi.slice().sort((a, b) => Number(a.updateid) - Number(b.updateid));
let testo = ordinati.map((r) => String(r.testo || '').trim()).filter(Boolean).join('\n');
if (!testo) testo = String(mioMsg.text || '').trim();   // rete di sicurezza

const messaggio = Object.assign({}, mioMsg, { text: testo });
return [{ json: {
  update_id: mioUpdate,
  message: messaggio,
  _buffer_uniti: ordinati.length || 1,
  _buffer_allegato: false,
  _da_cancellare: ordinati.map((r) => r.id).filter((x) => x != null)
} }];

// Una riga per ogni Id da togliere dalla coda: il nodo dopo cancella per Id,
// uno alla volta. Così un allegato non cancella mai la riga di un altro
// allegato che sta ancora aspettando il suo turno.
let ids = [];
try { ids = $('Buffer - Sono l\'ultimo?').first().json._da_cancellare || []; } catch (e) { ids = []; }
return ids.filter((x) => x != null).map((id) => ({ json: { id: id } }));

// GUARDIA SALVATAGGIO — 21/08/2026
// Nodo: fra «Format Telegram Output (intent)» e «TG - Send Dynamic», workflow
// Prenotazioni Transfer 6.0.
//
// Nasce dall'esecuzione 777940 del 21/08 alle 07:51:59. Agostino preme «💾 Salva subito»
// su un rientro. Parse transfer legge bene il transfer (21/08, 14:15, Cala Ponte Marina →
// Masseria Tarsia Morisco, 50, Incassare) ma con Id vuoto, e il gestionale risponde
// `rows: []`: NON HA SCRITTO NIENTE. Il bot gli manda lo stesso:
//     «✅ Conferma transfer — 💶 Tariffa: ⚠️ DA DEFINIRE»
// senza data, senza tratta, senza codice. Il transfer delle 14:15 di quel giorno non
// esisteva da nessuna parte, e lui credeva di averlo salvato.
//
// Due guasti in uno, e questo nodo li chiude tutti e due.
//
// (1) «Mai dichiarare un salvataggio che non è avvenuto». Se la ricevuta del gestionale
//     dice zero righe, la parola «Conferma» non si può usare.
//
// (2) La tariffa sparita. Quando la ricevuta è vuota, «Format Telegram Output (intent)»
//     ripiega su un parser che legge i campi dalla scheda con la regex `^\s*Tariffa\s*:`.
//     Le schede però cominciano con un'emoji («💰 Tariffa: 50,00€») e `\s` l'emoji non la
//     mangia: nessun campo combacia, e la tariffa — che era lì, scritta — esce
//     «⚠️ DA DEFINIRE». Stessa sorte per Data, Ora, Da, Per, Id. Qui i campi si leggono
//     con `[^\p{L}\n]*`, che è la forma già usata in tutto il resto del workflow.
//
// (3) 21/08 sera: la ricevuta torna INCOMPLETA — meno righe di quante schede sono state
//     spedite. Fino a stasera passava per «tutto a posto». Vedi il blocco «chi è stato
//     spedito e dalla ricevuta non torna».
//
// La guardia parla solo su prove: righe zero, righe monche, o scarto fra spedito e
// confermato. Se la ricevuta non si riesce a leggere, o il nodo del salvataggio non ha
// girato in questo giro, non tocca niente: meglio lasciare passare il messaggio di prima
// che inventarne uno sbagliato.
//
// Banco: banchi/te/banco-guardia-salvataggio.js (dati veri di 777940 e 777827).
const items = $input.all();

// ---- quante righe dice di aver scritto il gestionale ----
// -1 = non lo so. In quel caso non si tocca niente.
let righeScritte = -1;
try {
  let n = 0;
  for (const it of $('Salva via Parse transfer (intent)').all()) {
    const raw = it.json && it.json.rows;
    if (raw === undefined || raw === null) continue;
    const arr = typeof raw === 'string' ? (raw.trim() ? JSON.parse(raw) : []) : raw;
    if (Array.isArray(arr)) n += arr.length;
    else n += 1;
  }
  righeScritte = n;
} catch (e) { righeScritte = -1; }

// ---- chi è stato spedito e dalla ricevuta non torna — 21/08/2026 ----------------
// Esecuzione 781233, ore 19:14. Agostino preme «salva tutte le bozze in sospeso»: a Parse
// transfer arrivano TRE transfer, la ricevuta ne riporta UNO (riga 1289, Cala Ponte Hotel
// → Otella). A lui arriva «✅ Conferma transfer» di quello, e degli altri due — Masseria
// Tarsia Morisco ↔ Monopoli, 55€ l'uno, quella sera stessa — nessuno dice niente.
// La guardia scattava solo a righe ZERO. Uno su tre passava per «tutto a posto».
//
// Qui si confronta quello che è stato SPEDITO (payload_schede, prodotto dal codice di
// «Componi Payload Salvataggio») con quello che la ricevuta CONFERMA. Lo scarto si dice.
// Non si afferma che non sono stati scritti — non si sa: si dice che il gestionale non
// li ha confermati, che restano in registro e come rimandarli.
const _idsRicevuta = new Set();
try {
  for (const it of $('Salva via Parse transfer (intent)').all()) {
    const raw = it.json && it.json.rows;
    if (!raw) continue;
    const arr = typeof raw === 'string' ? (raw.trim() ? JSON.parse(raw) : []) : raw;
    for (const r of (Array.isArray(arr) ? arr : [arr])) {
      const id = r && (r.Id || r.id);
      if (id) _idsRicevuta.add(String(id).replace(/<\/?code>/g, '').trim());
    }
  }
} catch (e) {}

let _spediti = [];
try {
  _spediti = ($('Componi Payload Salvataggio').first().json.payload_schede || [])
    .map((x) => String(x || '').trim()).filter(Boolean);
} catch (e) { _spediti = []; }

const _nonConfermati = _spediti.filter((id) => !_idsRicevuta.has(id));

// per dire QUALI, non solo quanti: la tratta si pesca dal registro bozze, che in questo
// punto del giro è ancora quello di prima del salvataggio.
function _trattaDi(id) {
  try {
    for (const r of $('Leggi Bozze').all()) {
      const d = r.json && (r.json.Dati ?? r.json.dati);
      if (!d) continue;
      const reg = JSON.parse(String(d)) || {};
      const scheda = reg[id] && reg[id].b;
      if (!scheda) continue;
      const g = (nomi) => {
        const m = String(scheda).match(
          new RegExp('^[^\\p{L}\\n]*[ \\t]*(?:' + nomi + ')[ \\t]*:[ \\t]*(.+?)[ \\t]*$', 'imu'));
        return m ? String(m[1]).replace(/\s*🗺️\s*Maps\s*$/u, '').trim() : '';
      };
      const da = g('Da|From'), per = g('Per|To'), ora = g('Ora|Time'), data = g('Data|Date');
      const tratta = [da, per].filter(Boolean).join(' → ');
      return [data, ora, tratta].filter(Boolean).join(' · ');
    }
  } catch (e) {}
  return '';
}

function _avvisoNonConfermati() {
  if (!_nonConfermati.length) return '';
  const righe = ['⚠️ <b>' + _nonConfermati.length + (_nonConfermati.length === 1
      ? ' scheda non confermata dal gestionale</b>' : ' schede non confermate dal gestionale</b>'),
    'Ne ho mandate ' + _spediti.length + ', la ricevuta ne riporta ' + _idsRicevuta.size + '.'];
  for (const id of _nonConfermati) {
    const t = _trattaDi(id);
    righe.push('• ' + (t || 'scheda senza descrizione') + '\n  <code>' + id + '</code>');
  }
  righe.push('Non so se sono state scritte. Restano in registro: dimmi «riprova» e le '
    + 'rimando — stesso Id, quindi non si creano doppioni.');
  return righe.join('\n');
}

// ---- caso 1: ha scritto, ma la riga è monca ------------------------------------
// 21/08/2026, esecuzione 779301. Agostino manda un vocale: «Segna il transfer ORA da
// Auraterrae…». La trascrizione consegna «Segnal transfer URA da Auratier…» — la parola
// «ora» è finita dentro «transfer URA». L'agente scrive Nome: URA e lascia Data e Ora
// VUOTE, poi salva: riga 1271 sul gestionale con Data "" e Time "".
// A lui arriva «✅ Conferma transfer», senza un accenno.
// Una riga senza data non compare in NESSUNA lista del giorno: nessun autista la vede.
//
// Il sistema lo sapeva già in due punti e ha scritto lo stesso:
//   · «Componi Payload Salvataggio» aveva calcolato payload_monche con dentro quell'Id;
//   · «Validate Fields» in Parse transfer aveva _missingFields: ["Data","Ora"].
// Nessuno dei due valori viene letto da qualcuno.
//
// Qui NON si blocca il salvataggio: in «Validate Fields» c'è una decisione esplicita del
// 02/05/2026 — «NON scartare mai: meglio salvare un transfer incompleto e correggerlo a
// mano che droppare silenziosamente e perdere dati». Quella decisione però dà per scontato
// che Agostino SAPPIA che è incompleto. Quello che mancava non era il blocco: era dirlo.
// E non si riempie Data/Ora da soli: sarebbe indovinare su un dato suo.
if (righeScritte > 0) {
  const monche = [];
  try {
    for (const it of $('Salva via Parse transfer (intent)').all()) {
      const raw = it.json && it.json.rows;
      if (!raw) continue;
      const arr = typeof raw === 'string' ? (raw.trim() ? JSON.parse(raw) : []) : raw;
      for (const r of (Array.isArray(arr) ? arr : [arr])) {
        if (!r) continue;
        const data = String(r.Data || r.data || '').trim();
        const ora = String(r.Time || r.Ora || r.ora || '').trim();
        if (data && ora) continue;
        monche.push({
          id: String(r.Id || r.id || '').trim(),
          manca: (!data && !ora) ? 'data e ora' : (!data ? 'la data' : 'l\'ora'),
          da: String(r['Transfer > Da'] || r.Transfer_Da || '').trim(),
          per: String(r['Transfer < Per'] || r.Transfer_Per || '').trim(),
        });
      }
    }
  } catch (e) { return items; }

  if (!monche.length && !_nonConfermati.length) return items;

  const avviso = [_avvisoNonConfermati(), monche.map((m) => {
    const tratta = [m.da, m.per].filter(Boolean).join(' → ');
    return '⚠️ <b>Salvato senza ' + m.manca + '</b>'
      + (tratta ? ' — ' + tratta : '')
      + '\nNon comparirà in nessuna lista del giorno.'
      + (m.id ? '\n<code>' + m.id + '</code>' : '');
  }).join('\n\n')].filter(Boolean).join('\n\n');

  const coda = monche.length
    ? '\n\nScrivi «ora» per mettere adesso, oppure dimmi giorno e ora.'
    : '';
  const primo = (items[0] && items[0].json) || {};
  const testoPrima = (primo.telegram && primo.telegram.text) || '';

  return items.map((it, i) => {
    if (i !== 0) return it;
    const j = Object.assign({}, it.json || {});
    j.telegram = Object.assign({}, j.telegram, {
      text: avviso + coda + (testoPrima ? '\n\n' + testoPrima : ''),
      parse_mode: (j.telegram && j.telegram.parse_mode) || 'HTML',
    });
    j.salvataggio_monco = monche.map((m) => m.id).filter(Boolean);
    j.salvataggio_non_confermato = _nonConfermati;
    return { json: j };
  });
}

if (righeScritte !== 0) return items;

// ---- da qui in giù: il gestionale non ha scritto niente ----
const norm = $('Normalizer (kind/text/file_id)').first().json || {};
const scheda = String(norm.originalMessageText || '');

// I campi si leggono tollerando l'emoji davanti: è questo il punto che mangiava la tariffa.
// In coda alle righe dei luoghi il workflow appiccica «  🗺️ Maps»: quello si toglie.
function campo(nomi) {
  const re = new RegExp('^[^\\p{L}\\n]*[ \\t]*(?:' + nomi + ')[ \\t]*:[ \\t]*(.+?)[ \\t]*$', 'imu');
  const m = scheda.match(re);
  if (!m) return '';
  return String(m[1]).replace(/\s*🗺️\s*Maps\s*$/u, '').trim();
}

const data = campo('Data|Date');
const ora = campo('Ora|Time');
const da = campo('Da|From');
const per = campo('Per|To');
const tariffa = campo('Tariffa|Fare');
const nome = campo('Nome|Name');
const fornitore = campo('Fornitor\\w*|Supplier\\w*');
const id = campo('Id');

const righe = ['⚠️ <b>NON SALVATO</b> — il gestionale non ha scritto nessuna riga.', ''];
if (data) righe.push('📅 ' + data + (ora ? ' alle ' + ora : ''));
if (da) righe.push('📍 Da: ' + da);
if (per) righe.push('🎯 A: ' + per);
if (nome) righe.push('👤 ' + nome);
if (fornitore) righe.push('🏢 ' + fornitore);
// la tariffa si scrive SOLO se c'era davvero: se manca si dice che manca, non si inventa
if (tariffa) righe.push('💶 Tariffa: ' + tariffa);
else righe.push('💶 Tariffa: — (non c\'era nemmeno nella scheda)');
if (id) righe.push('', '<i>Id della scheda:</i> <code>' + id + '</code>');

righe.push('');
righe.push(id
  ? 'Il salvataggio è tornato indietro a mani vuote. Dimmi «riprova» e lo rifaccio.'
  : 'La scheda non porta nessun Id e il salvataggio non ne ha generato uno: senza Id il '
    + 'gestionale non scrive la riga. Dimmi «riprova» e lo rifaccio, ma controlla a mano '
    + 'prima di darlo per fatto.');

const testo = righe.join('\n');
const base = (items[0] && items[0].json) || {};
return [{ json: Object.assign({}, base, {
  telegram: { text: testo, parse_mode: 'HTML' },
  replyMarkupJson: null,
  salvataggio_a_vuoto: true,
}) }];

// === BOTTONE ANNULLA DOPO UN SALVATAGGIO PARTITO DA SOLO — 20/08/2026 ===
// Nodo: «Bottone Annulla» in Prenotazioni Transfer 6.0, fra «Format Telegram Output (intent)»
// e «TG - Send Dynamic».
//
// Va a coppia con la regola «salva e mostra» che sta dentro «Code in JavaScript»: quando una
// scheda completa viene salvata senza chiedere conferma, il messaggio che arriva ad Agostino
// deve portarsi dietro il modo di disfare, altrimenti gli si toglie una domanda e gli si
// toglie anche il controllo.
// L'annullo passa dalla cancellazione morbida di sempre: Allert = Cancellato, mai delete.
//
// Se il salvataggio invece l'ha confermato lui, qui non si tocca niente: il bottone
// comparirebbe su ogni conferma e diventerebbe rumore.
//
// Banco: banchi/te/banco-bottone-annulla.js
const items = $input.all();

let diretto = false;
try { diretto = !!$('Code in JavaScript').first().json.salvataggio_diretto; } catch (e) { diretto = false; }
if (!diretto || !items.length) return items;

// Gli Id da annullare sono quelli che il gestionale dice di aver scritto davvero,
// non quelli che il testo promette.
const ids = [];
try {
  for (const it of $('Salva via Parse transfer (intent)').all()) {
    const rows = it.json && it.json.rows;
    if (!rows) continue;
    const arr = typeof rows === 'string' ? JSON.parse(rows) : rows;
    for (const r of (Array.isArray(arr) ? arr : [arr])) {
      const id = String((r && (r.Id || r.id)) || '').replace(/<\/?code>/g, '').trim();
      if (id && ids.indexOf(id) === -1) ids.push(id);
    }
  }
} catch (e) {}
if (!ids.length) return items;

// callback_data: massimo 64 byte (limite Telegram).
//
// ⚠️ La parola conta. In questo bot «annulla» vuol dire «scarta la bozza, non salvarla» —
// è quello che fa il bottone ❌ Annulla accanto a Conferma. Ma qui la riga sul gestionale
// c'è GIÀ: se il comando dicesse «annulla», l'agente potrebbe limitarsi a buttare la bozza
// e lasciare la riga scritta. Il comando dice quindi «cancella», che è la strada della
// cancellazione morbida di sempre: Allert = Cancellato + nota ⛔, mai delete.
// Quello che Agostino LEGGE resta «Annulla»: è la parola sua.
const _byte = (s) => Buffer.byteLength(String(s), 'utf8');
const righe = [];

if (ids.length === 1) {
  const cb = 'cancella ' + ids[0];
  righe.push([{ text: '🗑️ Annulla — non era giusto',
                callback_data: _byte(cb) <= 64 ? cb : 'cancella l\'ultimo transfer salvato' }]);
} else if (ids.length <= 3) {
  // due o tre schede: un bottone per ognuna, con il suo Id preciso. Meglio tre bottoni
  // esatti di un comando solo che l'agente deve interpretare.
  ids.forEach((id, i) => {
    const cb = 'cancella ' + id;
    if (_byte(cb) <= 64) righe.push([{ text: '🗑️ Annulla il ' + (i + 1) + '°', callback_data: cb }]);
  });
  if (!righe.length) righe.push([{ text: '🗑️ Annulla tutti e ' + ids.length,
                                   callback_data: 'cancella gli ultimi ' + ids.length + ' transfer salvati' }]);
} else {
  righe.push([{ text: '🗑️ Annulla tutti e ' + ids.length,
                callback_data: 'cancella gli ultimi ' + ids.length + ' transfer salvati' }]);
}

items[0].json = Object.assign({}, items[0].json, {
  replyMarkupJson: JSON.stringify({ inline_keyboard: righe })
});
return items;
